  // Full-cell lens band colour (handoff #5). Light pastel on light theme,
  // deep tint on dark; minor collections slightly duller than major. With
  // "Key colours" OFF the bands fall back to one neutral maroon wash.
export function lensBand(hue,minor){
    if(!PREF.cof) return PREF.theme==="dark"?"rgba(138,43,43,.22)":"rgba(138,43,43,.13)";
    return PREF.theme==="dark"
      ? `hsl(${hue} ${minor?24:30}% ${minor?22:27}% / .9)`
      : `hsl(${hue} ${minor?40:58}% ${minor?80:87}% / .92)`;
  }

  // ── local-key/scale continuity tracker — JS port of harmonia/theory/local_key.py's
  // continuity_scale_track_v2 + consolidate_dominant_chains (2026-07-21). Operates on
  // (root pc, iReal quality tail) pairs already on hand (ch.root/ch.q), not token
  // strings — the algorithm itself (hold the diatonic collection until a chord's tones
  // contradict it, then jump to the nearest circle-of-fifths collection that fits) is
  // unchanged from the Python reference; see that module's docstring for the "why".
  // Ported here (not fetched from the server) because colouring is a pure function of
  // chords already in S.chords — no round trip needed, and this view must also recolour
  // instantly after an in-browser transpose (transposeTo() just re-renders the chart).
export const MAJOR_SCALE_IVS=[0,2,4,5,7,9,11];
export const MAJOR_COLL=[]; for(let c=0;c<12;c++) MAJOR_COLL.push(new Set(MAJOR_SCALE_IVS.map(i=>mod(c+i,12))));
export const HARMONIC_MIN_COLL=[]; for(let c=0;c<12;c++){ const s=new Set(MAJOR_COLL[c]); s.delete(mod(c+7,12)); s.add(mod(c+8,12)); HARMONIC_MIN_COLL.push(s); }
export const MELODIC_MIN_COLL=[]; for(let c=0;c<12;c++){ const s=new Set(MAJOR_COLL[c]); s.delete(mod(c+5,12)); s.delete(mod(c+7,12)); s.add(mod(c+6,12)); s.add(mod(c+8,12)); MELODIC_MIN_COLL.push(s); }
export const _subset=(a,b)=>{ for(const x of a) if(!b.has(x)) return false; return true; };
  // chord_pcs(token, include_bass=False) ported straight off (root, q) — the interval
  // set a chord contributes, weighted only in the Python version for estimate_key's
  // chroma histogram; the continuity tracker only needs SET membership, so weights are
  // dropped here and this returns a plain Set of absolute pitch classes.
export function coreTones(root,q){
    const ivs=new Set([0]);
    if(q.startsWith("sus")){
      if(q.indexOf("2")<0) ivs.add(5);
      ivs.add(q.indexOf("2")>=0?2:7);
      ivs.add(7);
    } else {
      if(q[0]==="-"||q[0]==="h"||q.startsWith("o")||q.startsWith("dim")||q.startsWith("m")) ivs.add(3);
      else ivs.add(4);
      if(q.startsWith("o")||q.startsWith("dim")||q.startsWith("h")||q.indexOf("b5")>=0) ivs.add(6);
      else if(q.startsWith("+")||q.startsWith("aug")||q.indexOf("#5")>=0) ivs.add(8);
      else ivs.add(7);
    }
    if(q.indexOf("^")>=0||q.indexOf("maj7")>=0||q.indexOf("M7")>=0) ivs.add(11);
    else if((q.startsWith("o")||q.startsWith("dim")) && q.indexOf("7")>=0) ivs.add(9);
    else if(q.indexOf("6")>=0 && q.indexOf("b6")<0) ivs.add(9);
    else if(q.indexOf("7")>=0 || q[0]==="-" || q[0]==="h" || q.startsWith("m")) ivs.add(10);
    const out=new Set(); ivs.forEach(iv=>out.add(mod(root+iv,12))); return out;
  }
export function fitsCollection(tones,c,root){
    if(_subset(tones,MAJOR_COLL[c])) return true;
    if(_subset(tones,HARMONIC_MIN_COLL[c])) return true;
    if(root===mod(c+9,12) && _subset(tones,MELODIC_MIN_COLL[c])) return true;
    return false;
  }
export function cofDist(a,b){ const d=Math.abs(mod(a*7,12)-mod(b*7,12)); return Math.min(d,12-d); }
export const keyLabelName=(tonic,mode)=>note(tonic)+" "+mode;
export function labelCollection(coll,run){
    const rel=mod(coll+9,12); let majHits=0,minHits=0,needsMinor=false;
    run.forEach(c=>{
      const cls=qClass(c.q);
      if(c.root===coll && cls==="maj") majHits++;
      else if(c.root===rel && (cls==="min"||cls==="m7b5")) minHits++;
      const t=coreTones(c.root,c.q);
      if(!_subset(t,MAJOR_COLL[coll]) && _subset(t,HARMONIC_MIN_COLL[coll])) needsMinor=true;
    });
    if(minHits>majHits) return [rel,"minor"];
    if(minHits===0 && majHits===0 && needsMinor) return [rel,"minor"];
    return [coll,"major"];
  }
export function continuityScaleTrackV2(seq,homeTonic,homeMode,lookahead){
    // CAUSAL by default (Louis's locked rule 2026-07-21): "the key holds until a
    // non-diatonic chord, no lookahead, never per-chord, min=triad." The jump
    // tie-break must NOT peek at future chords — a forced jump lands on the
    // nearest circle-of-fifths collection that fits the CURRENT chord, ties broken
    // by tonic index only. Was `lookahead||2` (a 2-chord peek); now defaults to 0.
    // Matches Python theory.local_key.continuity_scale_track_v2(..., lookahead=0),
    // the single source of truth. An explicit value (incl. 2) is still honoured for
    // A/B comparison, but the shipped key track is causal.
    lookahead=(lookahead===undefined)?0:lookahead;
    const n=seq.length; if(!n) return [];
    const tones=seq.map(c=>coreTones(c.root,c.q)), roots=seq.map(c=>c.root);
    const homeColl=homeMode==="major"?homeTonic:mod(homeTonic+3,12);
    let cur=homeColl; const coll=new Array(n);
    for(let i=0;i<n;i++){
      const t=tones[i], r=roots[i];
      if(fitsCollection(t,cur,r)){ coll[i]=cur; continue; }
      let cands=[]; for(let c=0;c<12;c++) if(fitsCollection(t,c,r)) cands.push(c);
      if(!cands.length){
        const counts=[]; for(let c=0;c<12;c++){ let n2=0; t.forEach(x=>{ if(MAJOR_COLL[c].has(x)) n2++; }); counts.push(n2); }
        const best=Math.max(...counts);
        for(let c=0;c<12;c++) if(counts[c]===best) cands.push(c);
      }
      const rank=c=>{ let la=0; for(let k=i+1;k<Math.min(i+1+lookahead,n);k++) if(fitsCollection(tones[k],c,roots[k])) la-=1; return [cofDist(c,cur),la,c]; };
      cands.sort((a,b)=>{ const ra=rank(a),rb=rank(b); return ra[0]-rb[0]||ra[1]-rb[1]||ra[2]-rb[2]; });
      cur=cands[0]; coll[i]=cur;
    }
    const out=new Array(n); let i=0;
    while(i<n){
      let j=i; while(j<n && coll[j]===coll[i]) j++;
      let tonic,mode;
      if(coll[i]===homeColl && homeMode==="minor"){ tonic=mod(homeColl+9,12); mode="minor"; }
      else [tonic,mode]=labelCollection(coll[i], seq.slice(i,j));
      for(let k=i;k<j;k++) out[k]={tonic,mode};
      i=j;
    }
    return out;
  }
export function consolidateDominantChains(track,seq,homeTonic,homeMode){
    const n=seq.length; if(!n) return track.map(d=>({...d}));
    const roots=seq.map(c=>c.root), isDom=seq.map(c=>qClass(c.q)==="dom");
    const out=track.map(d=>({...d})); let i=0;
    while(i<n){
      if(!(isDom[i] && i+1<n && mod(roots[i+1]-roots[i],12)===5)){ i++; continue; }
      let m=i; while(m+1<n && isDom[m+1] && mod(roots[m+1]-roots[m],12)===5) m++;
      if(m===i){ i++; continue; }
      let start=i;
      if(i-1>=0){ const pcls=qClass(seq[i-1].q); if((pcls==="min"||pcls==="m7b5") && mod(roots[i]-seq[i-1].root,12)===5) start=i-1; }
      let arrT,arrM;
      if(m+1<n && mod(roots[m+1]-roots[m],12)===5){ arrT=track[m+1].tonic; arrM=track[m+1].mode; }
      else { arrT=mod(roots[m]+5,12); arrM=arrT===homeTonic?homeMode:"major"; }
      for(let k=start;k<=m;k++) out[k]={tonic:arrT,mode:arrM};
      i=m+1;
    }
    return out;
  }
  // collection (always-major) index a {tonic,mode} label sits on — the quantity the
  // halo colour is keyed to, so "D minor" and its relative "F major" never fight for
  // two different hues when they're the SAME diatonic collection.
export const collOf=(tonic,mode)=>mode==="major"?tonic:mod(tonic+3,12);
  // A repeating section (chart_model's folded "×N" — chords carry the SAME
  // `reps` for the whole section) loops back to its own first chord — a
  // trailing ii-V aimed at exactly that pitch is real cyclic evidence the
  // single linear pass can't see (there's no "next chord" after the last one
  // in a one-pass array). 2026-07-21 user's own audit case: an Autumn-Leaves-
  // style A section (Am Am7 Am7 Am6 | Cmaj7 A7 | Dm7 G7 | C6 | Bø7 E7alt) in
  // home C major — the linear tracker's run-vote labels the trailing G7 C6
  // Bø7 E7alt block "C major" outright (C6 is a real, un-ambiguous tonic
  // hit; no minor evidence follows within this one pass to out-vote it). But
  // Bø7-E7alt is a ii-V whose target (A) is the section's OWN opening tonic —
  // once the loop is considered, they are unambiguously "A minor", while G7
  // C6 (the actual V7-I arrival) genuinely are "C major" and must stay that
  // way. A blunter fix — literally re-running the tracker with the section's
  // head appended as lookahead — was tried and rejected: it also flipped C6
  // to "A minor" (the vote over the appended material swamps the real
  // cadential arrival), which is wrong. This is the narrow, correct form of
  // "treat the repeat as a cycle": relabel ONLY a trailing dominant (plus its
  // own directly-preceding ii, m7/m7b5 a fifth above it, if present) whose
  // resolution target is exactly the section's own first chord's root —
  // nothing else in the run is touched.
export function resolveTrailingCadenceIntoRepeat(track, chords){
    const n=chords.length, out=track.map(d=>({...d}));
    let i=0;
    while(i<n){
      let j=i; const secIdx=chords[i].secIdx, reps=chords[i].reps;
      while(j<n && chords[j].secIdx===secIdx) j++;
      if(reps>1 && j>i){
        const lastIdx=j-1;
        if(qClass(chords[lastIdx].q)==="dom"){
          const domRoot=chords[lastIdx].root, target=mod(domRoot+5,12);
          if(chords[i].root===target){
            let start=lastIdx;
            if(lastIdx-1>=i){
              const pcls=qClass(chords[lastIdx-1].q);
              if((pcls==="min"||pcls==="m7b5") && mod(domRoot-chords[lastIdx-1].root,12)===5) start=lastIdx-1;
            }
            const arr=out[i];
            for(let k=start;k<=lastIdx;k++) out[k]={tonic:arr.tonic, mode:arr.mode};
          }
        }
      }
      i=j;
    }
    return out;
  }
export function keyTrackFor(chords,homeTonic,homeMode){
    const seq=chords.map(c=>({root:c.root,q:c.q}));
    const raw=continuityScaleTrackV2(seq,homeTonic,homeMode);
    const track=consolidateDominantChains(raw,seq,homeTonic,homeMode);
    return resolveTrailingCadenceIntoRepeat(track,chords);
  }

  // ── Harte parsing — the retired reinfer endpoint's response was the ONE
  // place labels arrived in Harte ("G:hdim7"), because that is the model's
  // native tongue; this ground-truth parser keeps the same convention.
export const NOTE_PC={C:0,"C#":1,Db:1,D:2,"D#":3,Eb:3,E:4,F:5,"F#":6,Gb:6,G:7,"G#":8,Ab:8,A:9,"A#":10,Bb:10,B:11};
export const HARTE_Q={maj:"",maj7:"^7",min:"-",min7:"-7","7":"7",hdim7:"-7b5",dim:"o",dim7:"o7","6":"6",min6:"-6",maj6:"6","9":"9","min9":"-7"};
export function parseLabel(l){ if(!l) return {root:0,q:""}; const p=String(l).split(":"); return { root: NOTE_PC[p[0]]!=null?NOTE_PC[p[0]]:0, q: HARTE_Q[p[1]]!=null?HARTE_Q[p[1]]:(p[1]||"") }; }
export function overlaps(a0,a1,b0,b1){ return Math.min(a1,b1)-Math.max(a0,b0) > 1e-6; }

  // ── Training-mode ground truth (McGill Billboard hand annotations) ──────
  // Only present on model.gt for songs from the training corpus (see
  // scripts/harmonia_server.py:_gt_chords_for_video) — pasted YouTube links
  // have no model.gt and render nothing here. Labels arrive in raw Harte
  // notation ("C:min7", "N"); parseLabel() is the same parser the reinfer
  // diff view uses, so GT typesets with the exact glyph vocabulary (TOK) the
  // inferred chords already use.
export function gtForSpan(t0,t1){
    if(!S.model || !S.model.gt || !S.model.gt.length) return null;
    const hits=S.model.gt.filter(g=>overlaps(t0,t1,g.t0,g.t1));
    if(!hits.length) return null;
    // dominant overlap first — boundary mismatches are expected (independent
    // beat grids), so just show the GT chord that covers most of this span.
    hits.sort((a,b)=>(Math.min(t1,b.t1)-Math.max(t0,b.t0))-(Math.min(t1,a.t1)-Math.max(t0,a.t0)));
    const main=hits[0];
    // "N" = no chord (silence/intro); "X" = McGill Billboard's own "can't
    // tell" marker — neither is a real root+quality, so both render as N.C.
    // rather than mis-parsing as a bogus C major (parseLabel would otherwise
    // silently default an unrecognised note letter to root 0).
    if(main.label==="N"||main.label==="X"){
      return {parsed:null, text:"N.C.", extra:hits.length>1};
    }
    const parsed=parseLabel(main.label);
    const text=note(parsed.root)+(TOK[parsed.q]!=null?TOK[parsed.q]:parsed.q);
    return {parsed, text, extra:hits.length>1};
  }
  // A GT hit "matches" the inferred chord at the family level (root + maj/
  // min/dom/dim/m7b5 class) — partial credit, not exact-voicing equality;
  // per project convention a maj7 vs maj GT disagreement isn't worth flagging.
export function gtMatches(gt,ch){
    if(!gt || !gt.parsed) return false;
    return gt.parsed.root===ch.root && qClass(gt.parsed.q)===qClass(ch.q);
  }

  // ── 3. CHART ────────────────────────────────────────────────────────────
export async function openChart(file,opts){
    if(!file) return;
    const push = !opts || opts.push!==false;
    try{
      const m=await api.get("/api/chart-model/"+file);
      loadModel(m);
      go("chart",{push});
      try{ localStorage.setItem("harmLastChart",file); }catch(e){}
    }catch(e){ toast("Could not open that chart"); go("library",{push}); }
  }
  // Flatten the ChartModel's sections→bars→chords into the working list the
  // renderer walks, and give every chord its time span in EACH pass of a
  // folded section (a ×2 section renders once but sounds twice — the playhead
  // and any re-infer still have to address both).
export function loadModel(m, opts){
    opts = opts || {};
    /* GARDER L'OUTIL, C'EST GARDER LE CONTEXTE DE TRAVAIL (Louis, 2026-09-17,
       sur iPhone : « quand je clique, je suis renvoyé sur la page read, je
       devrais rester sur annotate et avoir direct l'outil qui s'affiche »).
       L'outil de sections déplie le chart pour travailler dessus, donc il
       passe par ici — et le mode repartait à « read ». Le panneau de l'outil
       n'est peint qu'en mode annotate (voir plus bas, `S.mode==="annotate"
       && sectToolOn()`) : il disparaissait donc au moment précis où on
       l'ouvrait, et l'onglet du bas basculait sur Read sous ses doigts.
       Le bug était intermittent, ce qui l'a rendu difficile à voir : sur un
       chart déjà déplié `loadModel` n'est pas appelé et le mode survivait. */
    const modeAvant = S.mode;
    S.model=m; S.key=m.key.tonic; S.keyMode=m.key.mode||"major"; S.mode="read"; S.pending=[];
    if(opts.keepTool && modeAvant) S.mode=modeAvant;
    S._vlKey=null; S._vlTrack=null; S._vlTotals=null; S._lastCoachIdx=null;
    S._prompterSync=null; loopEngineDispose(false);
    S.playBar=-1; S.playRep=null; S.playTime=null;
    // S.chartChrome (delta2 §6): true = toolbar/rail/dock visibles, false =
    // lecture immersive (barre 3px + poignée + fade). Un chart s'ouvre
    // toujours chrome visible; seule la LECTURE en Read le retire après
    // 2,6s sans interaction (immersiveArm), et l'arrêt le ramène.
    S.chartChrome=true;
    closeVoicingCard(); clearTimeout(S._immTimer);
    setSpelling(m.key.tonic, m.key.mode);   // F♯m7 in E major, B♭7 in F major
    // Louis, 2026-08-08: a chord-less FIRST section is the intro — name it so,
    // hide it from the chart (Read), keep it in the form rail, and shift the
    // letters so the first REAL section reads A. Only a reps=1 leading
    // section qualifies (a ×N section plays real music later); named
    // sections (intro/outro/bridge/…) keep their names, only single letters
    // are re-assigned — same original letter, same new letter everywhere.
    S._hiddenIntroId=null;
    if(m.sections && m.sections.length>1){
      const first=m.sections[0];
      const chordless=(first.reps||1)===1 &&
        !(first.bars||[]).some(bar=>(bar||[]).some(c=>c && !c.nc));
      if(chordless){
        if(!/^intro/i.test(String(first.label||""))){ first.label="intro"; first.tag=""; }
        S._hiddenIntroId=first.id;
        const map={}; let next=0;
        m.sections.slice(1).forEach(s=>{
          const L=String(s.label||"");
          if(/^[A-Z]$/.test(L)){
            if(!(L in map)) map[L]=String.fromCharCode(65+(next++));
            s.label=map[L];
          }
        });
      }
    }
    S.sections=m.sections.map((s,i)=>({ id:s.id, label:s.label, tag:s.tag, reps:s.reps, spans:s.spans, barRanges:s.barRanges, idx:i }));
    const chords=[];
    // Build S.bars in the SAME walk, one entry PER model bar — crucially
    // INCLUDING held (empty) bars. A held bar carries no chord (the previous
    // chord sounds through it), but it must still occupy a grid cell: the
    // model's per-section `bars` array already keeps an empty [] slot for each
    // held bar (chart_model gives every bar 0..n_bars-1 a slot). The old code
    // rebuilt S.bars from the flat chord list via `barFirst`, so every held
    // bar — having no chord — produced no cell and silently vanished. That
    // collapsed a 2-bar held chord into 1 cell and shifted every following bar
    // left by one, desyncing the whole form (2026-07-17 "Yesterday" bug).
    const barsList=[];
    m.sections.forEach((s,si)=>{
      const base=s.spans[0][0];
      // 1st/2nd endings (2026-07-21): a folded reps≥2 section whose passes
      // diverge only in the last `tail` bars carries `endings`. Render the
      // shared prefix ONCE over all passes, then each variant's tail with spans
      // for ONLY the passes that use it — so each pass plays (and highlights)
      // its own real ending instead of replaying the representative's.
      const tail = (s.endings && s.endings.tail) || 0;
      const prefixLen = s.bars.length - tail;
      // Emit one grid bar: build its chords with a per-chord span mapper, and
      // tag the bar with rendering meta (secFirst / ending bracket info).
      // `s.barSpans` (chart_display.bar_spans_for_sections) is the server's
      // per-rendered-bar × per-pass time map, listed in exactly this emit order
      // — prefix bars, then each ending variant's tail. Walk it with the same
      // cursor so bar r gets row r, and never recompute it here (see the tspans
      // block below for what recomputing it cost).
      let rbCursor=0;
      const emitBar=(bar, meta, spanFor)=>{
        const cur={idxs:[], t0:null, t1:null, sec:s.label, secId:s.id,
                   reps:s.reps, held: bar.length===0,
                   barSpans: meta.spansRow || (s.barSpans && s.barSpans[rbCursor]) || null,
                   // LES PULSATIONS DE CETTE MESURE-LÀ (2026-09-18, Louis sur
                   // Virtual Insanity : « un passage à la fin qui ne fait que
                   // 2 temps, noté comme du 2/4, en fait c'est une demi-barre
                   // et puis ça reprend, très jamiroquai — il faut le noter »).
                   // `s.meters` suit exactement l'ordre d'émission de
                   // `s.barSpans` : tronc, puis la queue de chaque variant.
                   beats: (s.meters && s.meters[rbCursor]) || null,
                   secFirst: !!meta.secFirst, ending: meta.ending||null,
                   endingFirst: !!meta.endingFirst, endingOwn: !!meta.endingOwn,
                   endingPasses: meta.endingPasses||null};
        rbCursor++;
        bar.forEach((c,ci)=>{
          const spans=spanFor(c);
          const idx=chords.length;
          chords.push({ root:c.root, q:c.q, c:c.c, bass:(c.bass==null?-1:c.bass),
            confirmed:!!c.confirmed, nc:!!c.nc,
            // `n` (how many times the song plays this chord) and `sug` (the
            // model's ranked alternates) are what the annotation editor states
            // out loud — both must travel with the chord or the editor invents
            // its own (see playedLabel / candList, 2026-08-17).
            // `sugBass` = la ligne de basse LUE à l'attaque de l'accord
            // (2026-09-16). Même règle que `sug` : cette liste est blanche,
            // un champ qu'on n'y recopie pas n'arrive jamais dans l'éditeur.
            // `casc` = les têtes d'extension de musx (7e/9e/11e/13e) mises en
            // commun sur l'empan, pour le compas en cascade (2026-09-17).
            // Troisième champ à tomber dans ce piège après `sug` et
            // `sugBass` : cette liste blanche est une dette, elle ne se
            // plaint jamais, elle oublie (cf. known_issues).
            bar:c.bar, beat:c.beat, sug:c.sug||null, sugBass:c.sugBass||null,
            casc:c.casc||null,
            // `pedal` (2026-09-18) : quatrième champ à passer par cette liste
            // blanche — un champ qu'on n'y recopie pas n'arrive JAMAIS dans le
            // rendu ni dans l'éditeur, en silence (cf. known_issues.md, `sug`,
            // `sugBass`, `casc`, et le `carry` encore mort aujourd'hui).
            pedal:!!c.pedal,
            n:(c.n==null?0:c.n|0),
            var:c.var||null,   // l'autre lecture de cette case, sur un chart replié
            sec:s.label, secId:s.id, secIdx:si, reps:s.reps,
            barFirst: ci===0, secFirst: !!meta.secFirst && ci===0,
            t0:c.t0, t1:c.t1, spans });
          cur.idxs.push(idx);
          if(cur.t0===null) cur.t0=c.t0;
          cur.t1=(cur.t1===null)?c.t1:Math.max(cur.t1, c.t1);
        });
        barsList.push(cur);
      };
      const allPass = c => s.spans.map(sp=>[c.t0 + (sp[0]-base), c.t1 + (sp[0]-base)]);
      // shared prefix (or the whole section when there are no endings)
      const prefixBars = tail ? s.bars.slice(0, prefixLen) : s.bars;
      prefixBars.forEach((bar,bi)=>emitBar(bar, {secFirst: bi===0}, allPass));
      if(tail && s.endings){
        const blocs = endingBlocks(s, tail, prefixLen);
        blocs.forEach(g=>{
          const baseV = s.spans[g.passes[0]][0];
          const passSpan = c => g.passes.map(p=>[c.t0 + (s.spans[p][0]-baseV), c.t1 + (s.spans[p][0]-baseV)]);
          g.bars.forEach((bar,bi)=>emitBar(bar,
            {secFirst:false, ending:g.label, endingFirst: bi===0, endingOwn:g.own,
             endingPasses:g.passes, spansRow:g.spans[bi]},
            passSpan));
        });
        // Les passes qui prennent une fin ALTERNÉE, gardées sur la section :
        // c'est la bande de forme qui porte l'ordre (Louis : « noter pareil
        // sur le haut de la grille qui permet de suivre où on en est »),
        // puisque le crochet ne le porte plus dès qu'on écrit `B` / `B alt`.
        const alt=[]; blocs.forEach(g=>{ if(g.alt) alt.push(...g.passes); });
        if(S.sections[si]) S.sections[si].altPasses=alt;
      }
    });
    S.chords=chords;
    S.bars=barsList;
    // Held bars have no chord and thus no intrinsic time. Give each the span
    // between its neighbours (prev bar's end → next chorded bar's start) so the
    // playhead and swipe-merge (spanTime) stay monotonic across the held gap.
    for(let i=0;i<S.bars.length;i++){
      if(S.bars[i].t0!==null) continue;
      const prevT1=(i>0 && S.bars[i-1].t1!=null)?S.bars[i-1].t1:0;
      let nextT0=null;
      for(let j=i+1;j<S.bars.length;j++){ if(S.bars[j].t0!=null){ nextT0=S.bars[j].t0; break; } }
      S.bars[i].t0=prevT1;
      S.bars[i].t1=(nextT0!=null)?nextT0:prevT1;
    }
    
    // L'outil sections appartient au morceau qu'il annote. Sans cette
    // remise à zéro, ouvrir une AUTRE chanson gardait les marques de la
    // précédente, les peignait sur sa grille, et la sauvegarde automatique
    // les écrivait dans le fichier de la nouvelle (audit 2026-08-10).
    // `keepTool` est le rechargement INTERNE de l'outil (passage en vue
    // dépliée et retour) : là, il ne change pas de morceau.
    if(!opts.keepTool){ S.sectTool=null; S._foldedModel=null; }
    S.audioUrl=m.audio_url||"";
    // S.timeIndex ([{i, t0, t1, rep}] over every chord × pass, in time order) is
    // built AFTER the bar spans below — chord times are now derived from the
    // bar's, so it has to wait for them.
    // ── per-BAR time spans → the playhead tracks TIME against BARS, not chord
    // index, so held ("%") bars, N.C. bars and the intro row all highlight while
    // they sound (user report 2026-07-19). Within a folded ×k section every pass
    // maps back to the SAME rendered bar, so one rendered bar lights once per pass.
    //
    // THE MAP IS THE SERVER'S (2026-07-30). `sec.barSpans` is built once in
    // chart_display.bar_spans_for_sections, from BAR BOUNDARIES, and is the only
    // thing that answers "which rendered bar is sounding at time t". This block
    // used to build it here out of CHORD SUSTAIN times and got it wrong four
    // ways at once — Louis: "the play head does n'importe quoi ... it skips
    // sections, doesn't play the first bars when 2 consecutive bars share the
    // same chord, and ends up being on the wrong chords and being either early
    // or late":
    //   * a folded pass was the written phrase RIGIDLY TRANSLATED onto that
    //     pass's start (`c.t0 + span_k[0] - span_0[0]`), so a pass longer than
    //     what is written ran out early (This Love's 12-bar verse written as 8:
    //     8.2s with no bar at all, playhead frozen) and a shorter one overran
    //     (its 4-bar verse: 12s of verse bars claiming the bridge's time);
    //   * a held ("%") bar got `[previous chord's t1, next chord's t0]` = a
    //     ZERO-LENGTH span, so it never lit and its predecessor stayed lit for
    //     both bars — all 376 held bars on 25 charts were dead this way.
    // The beat snap that used to live here moved server-side too (it needs an
    // order guard now that a pass can be time-compressed to under a beat per
    // bar; see snap_bar_spans_to_beats).
    //
    // The `else` branch below is the pre-2026-07-30 reconstruction, kept ONLY
    // for a payload with no barSpans (an old baked file). Anything served by
    // /api/chart-model takes the first branch.
    for(let bi=0;bi<S.bars.length;bi++){
      const b=S.bars[bi];
      const srv=(b.barSpans||[]).filter(sp=>sp && sp.length===2);
      if(srv.length){
        b.tspans=srv.map(sp=>[sp[0],sp[1]]);
      } else if(b.idxs.length){
        const nrep=Math.max(1,...b.idxs.map(i=>(S.chords[i].spans||[]).length||1));
        b.tspans=[];
        for(let r=0;r<nrep;r++){
          let t0=Infinity,t1=-Infinity;
          b.idxs.forEach(i=>{ const sp=(S.chords[i].spans&&(S.chords[i].spans[r]||S.chords[i].spans[0]))||[S.chords[i].t0,S.chords[i].t1]; t0=Math.min(t0,sp[0]); t1=Math.max(t1,sp[1]); });
          b.tspans.push([t0,t1]);
        }
      } else {
        b.tspans=[[b.t0,b.t1]];   // held bar: neighbour-filled single span
      }
    }
    // A bar's CHORDS then split that bar's time, in proportion to how long each
    // is written for. Chord spans used to be reconstructed independently of the
    // bar's, so the metronome and the bar highlight could disagree about where a
    // pass even was; now there is one map and the chords hang off it.
    S.bars.forEach(b=>{
      if(!b.idxs.length || !b.tspans.length) return;
      const cs=b.idxs.map(i=>S.chords[i]);
      const w=cs.map(c=>Math.max(1e-6,(c.t1||0)-(c.t0||0)));
      const wsum=w.reduce((a,x)=>a+x,0)||1;
      cs.forEach(c=>{ c.spans=[]; });
      b.tspans.forEach(sp=>{
        const D=sp[1]-sp[0]; let cur=sp[0];
        cs.forEach((c,ci)=>{ const nx=(ci===cs.length-1)?sp[1]:cur+D*w[ci]/wsum; c.spans.push([cur,nx]); cur=nx; });
      });
    });
    S.timeIndex=[];
    S.chords.forEach((ch,i)=>(ch.spans||[]).forEach((sp,rep)=>S.timeIndex.push({i,t0:sp[0],t1:sp[1],rep})));
    S.timeIndex.sort((a,b)=>a.t0-b.t0);
    S.barTimeIndex=[];   // [{bi, t0, t1, rep}] over every bar × pass, time order
    S.bars.forEach((b,bi)=>b.tspans.forEach((sp,rep)=>S.barTimeIndex.push({bi,t0:sp[0],t1:sp[1],rep})));
    S.barTimeIndex.sort((a,b)=>a.t0-b.t0);
    // Metronome (2026-07-20) clicks on CHORD changes, not bar changes — a bar
    // can hold 2+ chords (split-bar feature), and barTimeIndex only tracks the
    // bar's outer envelope. Flatten every chord's own spans (repeats included)
    // into a separate time-ordered index so the click tracks real harmonic
    // rhythm, not just bar boundaries.
    S.chordTimeIndex=[];  // [{idx, t0, t1}] over every chord × repeat, time order
    S.chords.forEach((c,idx)=>{
      const spans=(c.spans&&c.spans.length)?c.spans:[[c.t0,c.t1]];
      spans.forEach(sp=>S.chordTimeIndex.push({idx,t0:sp[0],t1:sp[1]}));
    });
    S.chordTimeIndex.sort((a,b)=>a.t0-b.t0);
  }

  // ── chart chrome (UI refresh 2026-08-08, §2 / design 1a) ─────────────────
  // The four chrome rows (app bar, mode bar, legend, form strip) collapse to
  // ONE toolbar + ONE bottom dock; Analyse adds a one-line lens row. The
  // fullscreen chrome-handle/swipe machinery (2026-07-21) is retired WITH the
  // rows it existed to hide — one slim toolbar has nothing left to fold away.
  // Key + form are the title's subtitle (tap = rotor); Share and the Learn
  // ladder moved into the Aa sheet; Set bar 1 / Check merges moved into the
  // annotate ribbon, as words.

  /* ONE toolbar. Everything here is >= 44 on both axes. */
export function chartToolbar(){
    const m=S.model;
    const bar=el("div",
      `flex:0 0 auto;display:flex;align-items:center;gap:12px;`+
      `padding:calc(6px + env(safe-area-inset-top)) 14px 8px;background:${T.paper};`);
    bar.appendChild(kitIcon("‹", ()=>go("library"), "Back"));

    const tw=el("div","flex:1;min-width:0;");
    tw.appendChild(el("div",
      `font:italic 600 19px ${SERIF};color:${T.ink};`+
      `overflow:hidden;text-overflow:ellipsis;white-space:nowrap;`, songTitle(m)));
    // min-height 44 with negative margins: a full-size tap target (the kit's
    // floor) without adding visual height to the toolbar.
    const meta=el("button",
      `display:inline-flex;align-items:center;gap:6px;border:none;min-height:${SZ.control}px;`+
      `margin:-9px 0 -11px;background:none;padding:0;font:500 13px ${UI};color:${T.faint};cursor:pointer;`);
    meta.appendChild(el("span",`color:${T.ink};font-weight:600;`, note(S.key)+" "+(S.keyMode||"major")));
    if(m && m.form){ meta.appendChild(el("span","","·")); meta.appendChild(el("span","",m.form)); }
    meta.appendChild(el("span",`color:${T.accent};`,"↻"));
    meta.setAttribute("aria-label","Change key");
    meta.onclick=openRotor;
    tw.appendChild(meta);
    bar.appendChild(tw);

    // Les outils d'Annotate, derrière UN bouton, et seulement là (T2,
    // 2026-08-19). Dans les autres modes la barre est inchangée — Aa reste en
    // bout, aucun trou. Un écran = une chose à faire : Read lit, Annotate
    // corrige, et rien d'un mode n'apparaît dans un autre.
    if(S.mode==="annotate")
      bar.appendChild(kitIcon("···", openAnnotateTools, "Outils",
                              {style:`border:1px solid ${T.accent};color:${T.accent};`}));
    bar.appendChild(kitIcon("Aa", openPrefsSheet, "Preferences", {serif:true}));
    return bar;
  }

  /* La ligne qui reste au-dessus de la grille en Annotate. Elle remplace la
     légende dégradée du ruban, qui expliquait un code couleur en quatre teintes
     là où le geste tient en huit mots. */
export function annotateHint(){
    return el("div",`flex:0 0 auto;padding:0 16px 10px;background:${T.paper};`+
      `font:italic 12.5px ${SERIF};color:${T.faint};`,
      "touche un accord dont tu es sûr — il se verrouille");
  }

  /* The Analyse lens row + its ONE-LINE legend. Replaces the three outlined
     pills and the full-width legendFor() sentence block. */
export function analyseLens(){
    const wrap=el("div",`flex:0 0 auto;padding:0 14px 10px;background:${T.paper};`);
    wrap.appendChild(kitSegmented(
      [["function","Role"],["key","Local keys"],["global","Home key"]],
      ()=>S.colorMode,
      v=>{ S.colorMode=v; go("chart",{push:false}); },
      {height:SZ.control}));
    const L={
      function:[T.green, "colour marks what each chord does — home, setting up, pulling"],
      key:[lensBand(210,false), "colour marks where the tune borrows another key"],
      global:[lensBand(keyHue(collOf(S.key,S.keyMode)), S.keyMode==="minor"), "one wash — the whole song in its home key"]
    }[S.colorMode] || [null,""];
    wrap.appendChild(kitLegend(L[0], L[1]));
    return wrap;
  }

  /* Le clavier qui accompagne (Louis, 2026-08-08, seconde passe): en
     « Follow » il n'apparaît QUE lorsque le chart est en plein écran
     immersif — l'inverse d'avant, où il vivait dans le dock et disparaissait
     justement quand on jouait. Carte fine épinglée en bas, glyphe + noms +
     clavier, rien d'autre: le choix du style de voicing vit dans la feuille
     Aa (openPrefsSheet), pas ici — en immersif on ne pose pas de contrôles. */
export function immersiveCoach(){
    const p=el("div",
      `position:absolute;left:12px;right:12px;bottom:calc(12px + env(safe-area-inset-bottom));`+
      `z-index:30;background:${T.card};border:1px solid ${T.line};border-radius:16px;`+
      `padding:10px 12px;box-shadow:0 16px 36px -18px rgba(50,38,20,.5);`);
    const head=el("div","display:flex;align-items:center;gap:10px;margin-bottom:8px;");
    const cGlyph=el("div","flex:0 0 auto;"); head.appendChild(cGlyph);
    const cNames=el("div",`font:500 12px ${UI};color:${T.faint};flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;`,"");
    head.appendChild(cNames);
    p.appendChild(head);
    const ckb=el("div",""); p.appendChild(ckb);
    S._coachPanel=p; S._coachGlyph=cGlyph; S._coachNames=cNames; S._coachKb=ckb; S._coachNote=null;
    return p;
  }

  /* The dock: transport + Read/Analyse/Annotate/Practise, pinned in thumb
     reach. Replaces BOTH the old mode bar and the persistent bottom
     transport; syncTransport()/setPlayhead() target the S._dock* elements.
     "Practise" opens the prompter — the screen the old 9px reel toggle led
     to; a fourth segment beats hiding a whole screen behind a sheet. */
  // UNE GRILLE ÉCRITE N'A RIEN À JOUER (2026-09-18, import iReal). Un chart
  // importé depuis iReal Pro n'a pas d'audio : le transport (lecture, scrub,
  // A-B) et l'onglet Practise sont alors trois commandes visibles qui ne
  // font rien — et pire, `S.audio` n'est jamais remis à zéro entre deux
  // charts, donc Play jouait la chanson PRÉCÉDENTE par-dessus cette grille.
  // Le nettoyage de l'élément audio est dans `audio.js` (`syncTransport`) ;
  // ici, on ne montre simplement pas ce qui n'existe pas.
export const chartHasAudio=()=>!!S.audioUrl;
  // Taper une mesure ne peut « aller à » nulle part sans audio : le réglage
  // « tap = play » avale alors le geste au lieu d'ouvrir la fiche d'accord.
export const tapSeeks=()=>S.tapSeek && chartHasAudio();
export function chartDock(){
    const dock=el("div",
      `flex:0 0 auto;background:${T.card};border-top:1px solid ${T.line};`+
      `padding:12px 14px calc(10px + env(safe-area-inset-bottom));`+
      `box-shadow:0 -12px 30px -22px rgba(50,38,20,.5);`);
    const audible=chartHasAudio();

    const row=el("div","display:flex;align-items:center;gap:14px;");
    const play=el("button",
      `flex:0 0 auto;width:${SZ.primary}px;height:${SZ.primary}px;border-radius:50%;border:none;`+
      `background:${T.accent};color:#fff;cursor:pointer;`+
      `display:flex;align-items:center;justify-content:center;font:400 22px ${UI};`);
    playGlyph(play, S.playing, 18);
    play.setAttribute("aria-label", S.playing?"Pause":"Play");
    play.onclick=()=>{ if(S._loopEngine) loopEngineToggle(); else togglePlay(); setPlayBtn(); };
    S._playBtn=play;
    row.appendChild(play);

    const mid=el("div","flex:1;min-width:0;");
    // the 6px track sits inside a taller touch band — the seek target is 44
    const band=el("div","padding:19px 0;margin:-19px 0;cursor:pointer;touch-action:none;");
    const track=el("div",`height:6px;border-radius:3px;background:${T.line};overflow:hidden;`);
    const fill=el("div",`width:0%;height:100%;background:${T.accent};border-radius:3px;`);
    track.appendChild(fill); band.appendChild(track);
    const seekAt=(x)=>{ const r=track.getBoundingClientRect(); if(r.width) seekFrac((x-r.left)/r.width); };
    band.addEventListener("pointerdown",e=>{ band._down=true; seekAt(e.clientX); try{ band.setPointerCapture(e.pointerId); }catch(err){} });
    band.addEventListener("pointermove",e=>{ if(band._down) seekAt(e.clientX); });
    band.addEventListener("pointerup",()=>{ band._down=false; });
    band.addEventListener("pointercancel",()=>{ band._down=false; });
    const labels=el("div",
      `display:flex;justify-content:space-between;margin-top:6px;font:500 12px ${UI};color:${T.faint};`);
    const tNow=el("span","","0:00"), tWhere=el("span","",""), tEnd=el("span","","0:00");
    labels.appendChild(tNow); labels.appendChild(tWhere); labels.appendChild(tEnd);
    mid.appendChild(band); mid.appendChild(labels);
    row.appendChild(mid);
    S._dockFill=fill; S._dockNow=tNow; S._dockWhere=tWhere; S._dockEnd=tEnd;

    const loop=el("button",
      `flex:0 0 auto;width:${SZ.primary}px;height:${SZ.primary}px;border-radius:${SZ.radiusLg}px;`+
      `cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;`+
      ctlSkin(S._loopEngine?"on":"off"));
    loop.appendChild(el("div",`font:700 15px ${UI};`,"A–B"));
    loop.appendChild(el("div",`font:500 10px ${UI};opacity:.7;`,"loop"));
    loop.setAttribute("aria-label","Loop the four-bar phrase you are in");
    loop.onclick=()=>{ chartLoopToggle(); go("chart",{push:false}); };
    row.appendChild(loop);
    if(audible) dock.appendChild(row);

    const modes=kitSegmented(
      audible
        ? [["read","Read"],["analyse","Analyse"],["annotate","Annotate"],["practise","Practise"]]
        : [["read","Read"],["analyse","Analyse"],["annotate","Annotate"]],
      ()=>S.mode,
      v=>{
        // QUITTER L'OUTIL DE SECTIONS PAR CE BOUTON REND AUSSI LA VUE REPLIÉE
        // (Louis, 2026-09-17 : « quand je vais dans read j'ai le chart brut
        // avec les sections colorées, pas bon du tout »).
        // `writeSectionsToChart` charge EXPRÈS le chart déplié pour que l'outil
        // reste utilisable, et range le replié dans `S._foldedModel` ; seul
        // `closeSectionTool` le restituait. Passer en Read ne faisait que
        // changer `S.mode`, donc on relisait le déplié — le chart était
        // pourtant bien replié sur le disque. Le geste naturel après avoir
        // enregistré, c'est d'aller voir le résultat : il ferme l'outil.
        if(S.sectTool) closeSectionTool();
        if(v==="practise"){ go("prompter"); return; } S.mode=v; go("chart",{push:false}); },
      {font:13.5});
    if(audible) modes.style.marginTop="12px";
    dock.appendChild(modes);
    return dock;
  }

  // A–B loop on the chart: cycles the four-bar phrase the playhead is in
  // (the prompter's LOOP snap), through the same self-wrapping engine. The
  // interval here only carries the DISPLAY: once the engine ping-pongs onto
  // its own elements, the chart's timeupdate listener (on the main audio,
  // now paused) goes silent.
export function chartLoopToggle(){
    if(S._loopEngine){
      if(S._chartLoopTimer){ clearInterval(S._chartLoopTimer); S._chartLoopTimer=null; }
      loopEngineDispose(true);
      return;
    }
    const grid=(S.model&&S.model.barGrid)||[];
    if(grid.length<2 || !S.audio) return;
    let bi=0; { let lo=0,hi=grid.length-2; const t=nowTime();
      while(lo<=hi){ const mid=(lo+hi)>>1; if(grid[mid]<=t){ bi=mid; lo=mid+1; } else hi=mid-1; } }
    const g=Math.min(Math.floor(bi/4)*4, Math.max(0,grid.length-2));
    loopEngineStart(grid[g], grid[Math.min(g+4,grid.length-1)]);
    if(S._chartLoopTimer) clearInterval(S._chartLoopTimer);
    S._chartLoopTimer=setInterval(()=>{
      const en=S._loopEngine;
      if(!en || S.screen!=="chart"){ clearInterval(S._chartLoopTimer); S._chartLoopTimer=null; return; }
      const t=nowTime();
      const h=hitAtTime(t+PLAYHEAD_LEAD_S);
      if(h && h.bi!==S.playBar) setPlayhead(h.bi,h.rep,t+PLAYHEAD_LEAD_S);
      paintDockTime(t);
    },120);
  }
export function paintDockTime(t,dur){
    dur=dur||totalDur()||1;
    if(S._dockFill){ const f=Math.min(1,Math.max(0,t/dur)); S._dockFill.style.width=(f*100)+"%"; }
    if(S._dockNow) S._dockNow.textContent=fmt(t);
    if(S._dockEnd) S._dockEnd.textContent=fmt(dur);
    if(S._immFill){ const f=Math.min(1,Math.max(0,t/dur)); S._immFill.style.width=(f*100)+"%"; }
    // The form band moves on the CLOCK, like the dock's own fill (T1,
    // 2026-08-19). setPlayhead() only fires when the BAR changes — good enough
    // when the band lit one chip at a time, useless now that the tint has to
    // creep across a segment: an 8-bar A would advance in 8 visible jerks.
    // This is the one painter every clock source already calls (timeupdate,
    // the loop timer, seek), and it costs one style write per segment.
    paintFormRail(t);
  }

  // ── lecture immersive (delta2 §6 / design 3a): jouer, c'est lire ─────────
  // Pendant la lecture en Read, les deux bandeaux s'effacent après 2,6s sans
  // interaction et la grille prend tout l'écran. En Annotate on ne cache
  // JAMAIS: l'utilisateur y travaille, ses outils restent sous la main.
  // Trois gestes ramènent le chrome: la poignée (visible!), un glissé vers le
  // bas, un tap n'importe où entre deux accords. Un tap sur un ACCORD ne le
  // ramène pas — il ouvre la carte de voicing (S.piano==="tap").
export const IMMERSIVE_IDLE_MS = 2600;
export function immersiveEligible(){
    // Louis, 2026-08-08: une feuille ouverte (Aa, rotor, accord, partage…)
    // ne doit JAMAIS disparaître au bout de 2,6s — le go() du retrait
    // détruisait l'overlay avec le reste de l'écran. Tant qu'un overlay est
    // ouvert, on ne retire rien; closeOverlay() réarme le compte à rebours.
    return S.screen==="chart" && S.playing && S.mode==="read" &&
      !S._voicingCard && !root.querySelector("[data-overlay]");
  }
export function immersiveArm(){
    clearTimeout(S._immTimer);
    if(!immersiveEligible()) return;
    S._immTimer=setTimeout(()=>{
      if(!immersiveEligible() || !S.chartChrome) return;
      S.chartChrome=false;
      go("chart",{push:false});
    }, IMMERSIVE_IDLE_MS);
  }
export function immersiveWake(){
    if(S.screen!=="chart") return;
    if(!S.chartChrome){ S.chartChrome=true; go("chart",{push:false}); }
    immersiveArm();
  }
  // La barre de progression fine qui remplace le dock en immersif: 3px en
  // haut, aucune interaction, juste « où j'en suis ».
export function immersiveProgress(){
    const t=el("div",`flex:0 0 auto;height:3px;background:${T.line};`);
    const f=el("div",`width:0%;height:100%;background:${T.accent};`);
    t.appendChild(f); S._immFill=f;
    return t;
  }
  // La poignée doit être VISIBLE (delta2: elle ne l'était pas, et sans elle
  // le mode est une impasse). Cible 44px réelle, dessin discret — les marges
  // négatives l'empêchent de manger la hauteur gagnée.
export function immersiveHandle(){
    const row=el("div","flex:0 0 auto;display:flex;justify-content:center;padding:10px 0 6px;");
    const b=el("button",
      `width:72px;height:${SZ.control}px;margin:-14px 0 -10px;border:none;background:none;`+
      `cursor:pointer;display:flex;align-items:center;justify-content:center;`);
    b.setAttribute("aria-label","Show the controls");
    b.appendChild(el("span",`width:38px;height:4px;border-radius:2px;background:${T.rule};`));
    b.onclick=immersiveWake;
    row.appendChild(b);
    return row;
  }
  // un dégradé de 64px en bas: les dernières mesures s'estompent au lieu de
  // se couper net — ça dit « ça continue » sans occuper de place
export function immersiveFade(){
    return el("div",
      `position:absolute;left:0;right:0;bottom:0;height:64px;pointer-events:none;`+
      `background:linear-gradient(to top, ${T.paper}f5, ${T.paper}00);`);
  }

  // ── la carte de voicing flottante (delta2 §6) ────────────────────────────
  // Remplace openChordSheet() PENDANT LA LECTURE seulement (à l'arrêt, la
  // grande feuille garde tout son sens: c'est là qu'on édite). Elle flotte
  // au-dessus de la grille, ne coupe pas l'audio, et se referme au prochain
  // tap ailleurs. Mêmes claviers que le prompter (splitHands/renderHand) —
  // une seule implémentation pour les deux écrans.
export function openVoicingCard(idx, anchorEl){
    if(S.piano==="never") return;      // réglage Aa: le piano ne monte jamais
    closeVoicingCard();
    const ch=S.chords[idx]; if(!ch || ch.nc) return;
    const lv=learnLevel(), q=dispQ(ch.q);
    let m;
    if(S.coachStyle==="smooth"){
      const t=vlTrack(), p=t&&t[idx];
      m=p?p.midis:withBass(voClose(ch.root,q),ch.root,(lv>=3)?ch.bass:-1);
    } else {
      const m0=voicingByStyle(ch.root,q,S.coachStyle);
      m=(S.coachStyle==="rootless")?m0:withBass(m0,ch.root,(lv>=3)?ch.bass:-1);
    }
    const card=el("div",
      `position:absolute;left:12px;right:12px;bottom:calc(14px + env(safe-area-inset-bottom));`+
      `z-index:40;background:${T.card};border:1px solid ${T.line};border-radius:18px;`+
      `padding:14px 14px 12px;box-shadow:0 20px 44px -18px rgba(50,38,20,.55);`+
      `animation:ap-in .22s ease both;`);
    card.setAttribute("data-voicing-card","1");
    const head=el("div","display:flex;align-items:center;gap:10px;margin-bottom:12px;");
    head.appendChild(glyph(ch.root, q, 30, chordDepth(ch), T.ink, (lv>=3)?ch.bass:-1));
    const names=el("div",`flex:1;min-width:0;font:600 13px ${UI};color:${T.faint};overflow:hidden;text-overflow:ellipsis;white-space:nowrap;`);
    head.appendChild(names);
    head.appendChild(kitIcon("×", closeVoicingCard, "Close"));
    card.appendChild(head);
    const body=el("div","display:flex;flex-direction:column;gap:8px;");
    card.appendChild(body);
    const {left,right}=splitHands(m);
    names.innerHTML=`<span style="color:${T.accent}">L `+left.map(x=>note(mod(x,12))).join(" ")+
                    `</span> · <span style="color:#2a6fb0">R `+right.map(x=>note(mod(x,12))).join(" ")+`</span>`;
    [["R",right,"chord"],["L",left,"bass"]].forEach(([tag,mids,role])=>{
      const r=el("div","display:flex;align-items:center;gap:9px;");
      r.appendChild(el("div",
        `flex:0 0 auto;width:22px;font:700 11px ${UI};letter-spacing:.08em;color:${T.faint};`,tag));
      const host=el("div","flex:1;min-width:0;");
      r.appendChild(host); body.appendChild(r);
      renderHand(host, mids, 58, role);
      host.style.flex="1";     // renderHand réécrit cssText — le piège connu
    });
    card.appendChild(el("div",
      `margin-top:10px;font:italic 12.5px ${SERIF};color:${T.faint};`,
      "la musique continue · touche ailleurs pour refermer"));
    // tap sur la carte = entendre le voicing; ne se referme pas
    card.onclick=e=>{ if(e.target.tagName!=="BUTTON"){ e.stopPropagation(); playMidis(m); } };
    S._screenEl.appendChild(card);
    S._voicingCard=card;
    if(anchorEl) anchorEl.setAttribute("data-voicing-open","1");
    S._voicingAnchor=anchorEl||null;
    // un tap n'importe où ailleurs referme — capture, pour passer avant les
    // handlers des cellules
    S._voicingDismiss=e=>{ if(!card.contains(e.target)) closeVoicingCard(); };
    setTimeout(()=>document.addEventListener("pointerdown", S._voicingDismiss, true), 0);
    haptic();
  }
export function closeVoicingCard(){
    if(S._voicingDismiss){
      document.removeEventListener("pointerdown", S._voicingDismiss, true);
      S._voicingDismiss=null;
    }
    if(S._voicingAnchor){ S._voicingAnchor.removeAttribute("data-voicing-open"); S._voicingAnchor=null; }
    const c=S._voicingCard; S._voicingCard=null;
    if(!c) return;
    c.style.animation="ap-in .16s reverse both";
    setTimeout(()=>{ if(c.parentNode) c.parentNode.removeChild(c); }, 150);
    immersiveArm();
  }
export function renderChart(){
    const w=screenWrap();
    if(S.chartChrome){
      S._immFill=null;
      w.appendChild(chartToolbar());
      // FORM RAIL as the second (and last) chrome row above the grid — the
      // whole song on one line, pinned while the grid scrolls under it
      // (Louis, 2026-07-30: the timeline lives in the chart, never folded away).
      const rail=buildFormRail(); if(rail) w.appendChild(rail);
      if(S.mode==="analyse") w.appendChild(analyseLens());
      if(S.mode==="annotate") w.appendChild(annotateHint());
    } else {
      w.appendChild(immersiveProgress());
      // LA FORME NE SE REPLIE JAMAIS (Louis, 2026-09-18 : « le overhead view
      // des sections il faudrait qu'il soit tout le temps visible sur le
      // chart, même en vue minimaliste »). C'est la seule chose qui dit OÙ
      // ON EN EST dans le morceau — et c'est justement en lecture, quand
      // tout le reste a disparu, qu'on en a le plus besoin. Elle descend à
      // 16px ici (le chrome complet en prend 22) : la place gagnée par le
      // mode immersif reste gagnée, la forme ne coûte que 16px de plus que
      // la barre de progression qu'elle prolonge.
      const railImm=buildFormRail({h:16}); if(railImm) w.appendChild(railImm);
      w.appendChild(immersiveHandle());
      // le clavier qui accompagne (Follow) ne vit QUE dans cet état — quand
      // tout le reste a disparu (Louis, 2026-08-08, l'inverse d'avant)
      if(S.piano==="follow") w.appendChild(immersiveCoach());
    }

    // Densité iReal (Louis 2026-08-02): le chart occupe l'écran — marges
    // latérales minces, le treillis va presque bord à bord comme iRealB.
    const body=el("div",`flex:1;min-height:0;overflow-y:auto;padding:10px 7px 24px;background:${T.paper};`); body.className="ap-scroll";
    const sheet=el("div","max-width:720px;margin:0 auto;");
    sheet.appendChild(buildRefineBand());
    // L'outil sections est REVENU (Louis, 2026-08-15 : « mets moi le MÊME
    // chart que d'habitude, la même interface, juste chart brut, comme ça je
    // peux aussi écouter les sections tout ça, et par dessus juste une mini
    // interface d'annotation »). Il avait été démonté la veille au profit de
    // Soudure ; ce qu'il voulait, c'était l'annotation SUR le vrai chart, pas
    // une page à part. Le panneau reste minuscule — des pastilles de lettres
    // et une ligne d'état — et c'est le chart de l'app qui fait le reste :
    // les accords, le son, la tête de lecture, l'écoute d'une section.
    // T2 (2026-08-19) : aucun contrôle de section hors Annotate — et même en
    // Annotate le panneau n'apparaît qu'une fois ARMÉ. Le bouton qui l'armait
    // vivait sur le chart en permanence, dans les trois modes ; sa porte est
    // maintenant la ligne « Redessiner les sections » de la feuille Outils.
    if(S.mode==="annotate" && sectToolOn()) sheet.appendChild(buildSectionTool());
    sheet.appendChild(buildIReal());
    body.appendChild(sheet);
    w.appendChild(body);

    if(S.chartChrome) w.appendChild(chartDock());
    else w.appendChild(immersiveFade());
    // §6: tout geste rappelle le chrome et relance le compte à rebours — tap
    // hors accord, glissé vers le bas, poignée. Un tap sur un ACCORD ne le
    // rappelle pas (il ouvre la carte de voicing), ni un tap sur la carte.
    let _swY=null;
    w.addEventListener("pointerdown", e=>{
      if(e.target.closest("[data-voicing-card]")) return;
      _swY=e.clientY;
      if(!e.target.closest("[data-chord-cell]")) immersiveWake();
    });
    w.addEventListener("pointermove", e=>{
      if(_swY!=null && e.clientY-_swY>36){ _swY=null; immersiveWake(); }
    });
    w.addEventListener("pointerup", ()=>{ _swY=null; });
    immersiveArm();
    return w;
  }
  // ── le liseré « ça continue en fond » ────────────────────────────────────
  // Le chart affiché est le BRUT : mesures + accords + audio, une seule
  // section « A », une gamme approchée. Les sections et l'analyse harmonique
  // arrivent quelques dizaines de secondes plus tard et réécrivent le même
  // fichier. Ce liseré est la seule chose qui le dit — discret, une ligne,
  // au-dessus de la grille, jamais un écran bloquant.
  // Toujours présent dans le DOM (vide quand il n'y a rien à dire) pour que
  // paintChartRefining puisse le remplir sans reconstruire la page — un
  // re-render complet ferait sauter la position de défilement.
export function buildRefineBand(){
    const b=el("div","margin:0 0 8px;");
    S._refineBand=b; paintChartRefining();
    return b;
  }
export function paintChartRefining(){
    const b=S._refineBand; if(!b) return;
    clear(b); b.style.display="none";
    const file=S.model&&S.model.file; if(!file) return;
    const box=(bg,bd)=>el("div",`display:flex;align-items:center;gap:9px;padding:7px 11px;background:${bg};border:1px solid ${bd};border-radius:11px;`);
    if(S.refineReady===file){
      const w=box(T.card,T.accent);
      w.appendChild(el("div",`flex:1;font:600 12px ${UI};color:${T.ink};`,"Sections et gamme prêtes"));
      const btn=el("button",`border:none;background:${T.accent};color:#fff;border-radius:9px;padding:6px 12px;font:600 12px ${UI};cursor:pointer;`,"Recharger");
      btn.onclick=()=>{ S.pending=[]; S.mode="read";
                        applyRefinement(file,{}); };
      w.appendChild(btn); b.appendChild(w); b.style.display="block"; return;
    }
    if(S.refining && S.refining.file===file){
      const w=box(T.card,T.line);
      const dot=el("div",`flex:0 0 auto;width:13px;height:13px;border-radius:50%;border:2px solid transparent;border-top-color:${T.accent};animation:ap-spin .8s linear infinite;`);
      w.appendChild(dot);
      w.appendChild(el("div",`flex:1;font:500 11.5px ${UI};color:${T.faint};`,
        "Sections et gamme en cours — joue, le chart se mettra à jour tout seul."));
      b.appendChild(w); b.style.display="block";
    }
  }
  // ── the form timeline ────────────────────────────────────────────────────
  // One clickable chip per section OCCURRENCE, in play order, consecutive
  // repeats folded to ×N — e.g. `A×2  B  A  B  A  D  B×3`. Built from the
  // sections' own barRanges rather than from the `form` string, so the letters
  // shown here are exactly the letters written in the chart below it: since the
  // >=8-bar grouping and the 1st/2nd-ending collapse run server-side, the
  // detector's finer-grained form (`A×4 B×3 C A×3 …`) names sections that no
  // longer appear on the page, and showing those would be a chart that
  // disagrees with its own legend.
  // b0/b1 are SONG bars (what the chip's tooltip says); t0/t1 are the run's real
  // seconds (what the highlight is keyed on — see paintFormChip); rb0 is where
  // the run starts in the RENDERED grid, which is a different index space again
  // because the grid writes each section once.
  // LES FINS, REGROUPÉES ET NOMMÉES (Louis, 2026-09-18, sur This Love :
  // « 3 des 4 fins sont les mêmes, ça sert à rien de les écrire 3 fois »).
  //
  // DEUX FINS SONT LA MÊME quand elles posent les mêmes FONDAMENTALES, mesure
  // par mesure. La qualité (`F-` / `F7` / `F`) et un N.C. terminal sont du
  // bruit de modèle : c'est ce qui faisait écrire trois fois la même fin.
  // Mesuré avant d'agir (2026-09-18) : sur les 48 fins de la bibliothèque
  // cette fusion n'en retire que 2, et les deux sont sur ce morceau — ce
  // n'est donc PAS un levier général, c'est ce qui rend ce chart-là lisible.
  // Ce qu'elle ne résout pas : le groupe s'écrit avec les accords de sa
  // PREMIÈRE passe, pas avec un consensus des siennes. Voter entre elles
  // serait une loi de repli, à arbitrer à l'oreille, pas une règle d'écriture.
  //
  // COMMENT ON LES NOMME — le critère n'est pas combien de fins, c'est :
  // une fin couvre-t-elle plusieurs passes ?
  //   * chaque fin = une passe  → `1.` `2.` `3.` : « 1re fois ceci, 2e fois
  //     cela » est vrai (14 des 21 sections à fins de la bibliothèque) ;
  //   * une fin en couvre plusieurs → il n'y a plus de « deuxième fois » et
  //     le numéro ment (7 sections sur 21). On écrit alors la fin CLASSIQUE
  //     en ligne, comme la vraie queue de la section, et les autres dessous
  //     en `B alt`.
  // « Classique » = LA PREMIÈRE RÉPÉTITION, pas la plus fréquente (arbitrage
  // de Louis, 2026-09-18, sur la page docs/plots/fins_alt_3morceaux.html).
  // Conséquence assumée : sur This Love l'« alt » est jouée 3 fois et la
  // classique 2 — c'est l'ordre d'écoute qui nomme, pas le décompte.
export function endingBlocks(s, tail, prefixLen){
    const vs=(s.endings && s.endings.variants) || [];
    const bs=s.barSpans || [];
    const cle=bars=>bars.map(b=>b.filter(c=>!c.nc).map(c=>((c.root%12)+12)%12).join(",")).join("|");
    const gs=[];
    vs.forEach((v,vi)=>{
      const k=cle(v.bars);
      let g=gs.find(x=>x.k===k);
      if(!g) gs.push(g={k, vi:[], passes:[]});
      g.vi.push(vi); g.passes=g.passes.concat(v.passes||[]);
    });
    gs.forEach(g=>{
      g.passes.sort((a,b)=>a-b);
      // l'écriture de référence est celle de la passe la PLUS TÔT jouée: ses
      // temps d'accord sont calés sur `s.spans[g.passes[0]]`, ce que
      // `passSpan` suppose chez l'appelant.
      let rep=g.vi[0], best=Infinity;
      g.vi.forEach(vi=>{ const p=Math.min.apply(null, vs[vi].passes||[Infinity]);
                         if(p<best){ best=p; rep=vi; } });
      g.bars=vs[rep].bars;
      // les temps: une ligne par mesure de queue, toutes les passes du groupe,
      // remises dans l'ordre chronologique — `playRep` indexe cette liste.
      g.spans=[];
      for(let j=0;j<tail;j++){
        let row=[];
        g.vi.forEach(vi=>{ row=row.concat(bs[prefixLen+vi*tail+j]||[]); });
        g.spans.push(row.slice().sort((a,b)=>a[0]-b[0]));
      }
    });
    gs.sort((a,b)=>a.passes[0]-b.passes[0]);
    const lettre=String(s.label||"");
    const chacunSaPasse=gs.every(g=>g.passes.length===1);
    gs.forEach((g,gi)=>{
      if(chacunSaPasse){ g.label=(gi+1)+"."; g.own=gi>0; g.alt=false; }
      else if(gi===0){ g.label=lettre; g.own=false; g.alt=false; }
      else { g.label=lettre+" alt"+(gs.length>2?(" "+gi):""); g.own=true; g.alt=true; }
    });
    return gs;
  }

export function formRuns(){
    const m=S.model; if(!m||!m.sections) return [];
    const occ=[];
    m.sections.forEach((s,si)=>(s.barRanges||[]).forEach((r,k)=>occ.push({
      si, k, b0:r[0], b1:r[1], label:s.label, secId:s.id,
      t0:(s.spans&&s.spans[k])?s.spans[k][0]:null,
      t1:(s.spans&&s.spans[k])?s.spans[k][1]:null })));
    occ.sort((a,b)=>a.b0-b.b0);
    const runs=[];
    occ.forEach(o=>{
      const L=runs[runs.length-1];
      // `ks` = l'indice de PASSE de chaque occurrence du segment. Sans lui la
      // bande sait « jouée n fois » mais plus LAQUELLE est laquelle — or
      // c'est exactement ce qu'on doit y lire depuis qu'une fin peut être
      // `B alt` sur certaines passes seulement (Louis, 2026-09-18).
      if(L && L.label===o.label && L.b1+1===o.b0){ L.b1=o.b1; L.n++; L.ks.push(o.k); if(o.t1!=null) L.t1=o.t1; }
      else runs.push({label:o.label, b0:o.b0, b1:o.b1, n:1, t0:o.t0, t1:o.t1, ks:[o.k], si:o.si,
                      secId:o.secId, rb0:(S.bars||[]).findIndex(b=>b.secId===o.secId)});
    });
    return runs;
  }
  // ── the form BAND (cleanup 2026-08-19, T1) ───────────────────────────────
  // It is a scale model of the song with the playhead running through it, not
  // a row of buttons. The 44px chip rail it replaces wrapped to a second line
  // past ~10 runs and ate a third of the space above the grid; on Louis's
  // worst case (A×3 B A×3 B A×3 B bridge B A×3 = 17 passes) it was three rows
  // of chrome. Two rules make 17 passes fit on ONE 22px line:
  //   * consecutive passes of the SAME section are ONE segment, with N−1
  //     hairlines inside saying "played N times" — no ×N left to write;
  //   * a segment's width is its share of the DURATION, so an 8-bar A and a
  //     2-bar tag are not drawn the same size.
  // The 44px touch floor is won the way STYLE.md asks for it: padding and
  // negative margins on an invisible tap layer, never by growing the drawing.
export const FORM_BAND_H = 22;

  // Grouping happens DOWNSTREAM of formRuns(), which is left exactly as it is:
  // it already merges bar-contiguous repeats, and this rejoins the repeats it
  // had to split (a pass the fold rewrote, an occurrence with a hole in it).
export function formGroups(){
    const out=[];
    formRuns().forEach(r=>{
      const L=out[out.length-1];
      if(L && L.secId===r.secId){
        L.n+=r.n; L.b1=r.b1; L.ks=L.ks.concat(r.ks||[]);
        if(r.t1!=null) L.t1=r.t1;
        if(L.t0==null && r.t0!=null) L.t0=r.t0;
      } else out.push({secId:r.secId, label:r.label, b0:r.b0, b1:r.b1, si:r.si,
                       n:r.n, t0:r.t0, t1:r.t1, rb0:r.rb0, ks:(r.ks||[]).slice()});
    });
    return out;
  }

  // A…H keep their printed letter. A NAMED section (bridge, intro, solo…) is
  // written as its lowercase initial in Georgia italic bordeaux — `bridge` → b
  // — because the full word does not fit a 20px segment and a truncation with
  // dots reads as noise. The name itself lives in title/aria-label (and, from
  // T3, in the section editor).
export function formTag(label){
    const s=String(label||"").trim();
    // A' est une LETTRE, pas un nom : sur Bora Bora la bande écrivait « a » en
    // italique bordeaux à côté d'un « A » droit, deux choses qui se ressemblent
    // pour deux choses qui n'ont rien à voir. Une lettre garde son prime ou son
    // chiffre et son dessin de lettre.
    // A-Z, pas A-H (2026-09-18) : la borne à H datait d'un temps où seul le
    // détecteur audio nommait les sections et dépassait rarement 8. Un chart
    // iReal importé numérote dans l'ordre de jeu et va jusqu'à J ou plus —
    // ses lettres tombaient dans la branche « nom de section » et s'écrivaient
    // en bas de casse, italique, bordeaux, juste à côté des vraies lettres :
    // exactement le défaut que le commentaire ci-dessus décrit sur Bora Bora.
    if(/^[A-Z]['′´0-9]?$/.test(s)) return {text:s, css:`font:700 11px ${UI};color:${T.ink};`};
    return {text:(s[0]||"?").toLowerCase(), css:`font:italic 700 11px ${SERIF};color:${T.accent};`};
  }

  // opts.h — the band's height. 22 above the grid; T3's editor and T5's
  // prompter reuse this same builder at their own heights.
export function buildFormRail(opts){
    const H=(opts&&opts.h)||FORM_BAND_H;
    const PAD=Math.max(0,Math.round((SZ.control-H)/2));   // 22 → 11, 16 → 14
    const groups=formGroups();
    if(groups.length<2) return null;

    const wrap=el("div",`flex:0 0 auto;padding:0 14px 12px;background:${T.paper};`);
    const rail=el("div",`display:flex;gap:2px;height:${H}px;`);
    rail.setAttribute("data-form-band","1");
    wrap.appendChild(rail);
    S._formChips=[];

    // Width ∝ played duration. An iReal import carries no spans at all ([0,0]
    // everywhere), and there the pass COUNT is the only honest proportion left.
    const spanOf=g=>(g.t0!=null && g.t1!=null && g.t1>g.t0) ? (g.t1-g.t0) : 0;
    const timed=groups.some(g=>spanOf(g)>0);

    groups.forEach(g=>{
      const grow = timed ? Math.max(spanOf(g), .001) : g.n;
      const seg=el("div",`position:relative;flex:${grow} 1 0;min-width:14px;height:${H}px;`);

      // The DRAWING, clipped to its rounded box: progress tint, repeat
      // hairlines, one label. It never receives a touch — the zones below do.
      const vis=el("div",`position:absolute;inset:0;border-radius:5px;overflow:hidden;`+
        `background:${T.card};border:1px solid ${T.line};pointer-events:none;`+
        `transition:border-color .14s;`);
      // LA PASSE QUI FINIT AUTREMENT (Louis, 2026-09-18 : « noter pareil sur
      // le haut de la grille qui permet de suivre où on en est »). Depuis
      // qu'une fin peut s'écrire `B` / `B alt` au lieu de `1.` / `2.`, le
      // crochet ne dit plus QUAND — il dit seulement qu'une autre fin
      // existe. C'est ici que l'ordre se lit : la cellule de la passe
      // concernée porte le lavis et le trait d'accent du crochet.
      const alt=new Set(((S.sections[g.si]||{}).altPasses)||[]);
      if(alt.size) (g.ks||[]).forEach((k,i)=>{
        if(!alt.has(k)) return;
        vis.appendChild(el("div",`position:absolute;top:0;bottom:0;left:${i*100/g.n}%;`+
          `width:${100/g.n}%;background:rgba(138,43,43,.13);`+
          `border-bottom:2px solid ${T.accent};`));
      });
      const head=el("div",`position:absolute;left:0;top:0;bottom:0;width:0;background:rgba(138,43,43,.14);`);
      vis.appendChild(head);
      for(let i=1;i<g.n;i++)
        vis.appendChild(el("div",`position:absolute;top:3px;bottom:3px;width:1px;`+
          `left:${i*100/g.n}%;background:${T.line};`));
      const tag=formTag(g.label);
      const tw=el("span",tag.css,tag.text);
      const lab=el("div","position:absolute;inset:0;display:flex;align-items:center;justify-content:center;");
      lab.appendChild(tw); vis.appendChild(lab);
      seg.appendChild(vis);

      const nAlt=(g.ks||[]).filter(k=>alt.has(k)).length;
      const name=g.label+(g.n>1?(" ×"+g.n):"")+", bars "+(g.b0+1)+"–"+(g.b1+1)+
        (nAlt?(" — "+nAlt+(nAlt>1?" passes finissent":" passe finit")+" en « "+g.label+" alt »"):"");
      seg.title=name;

      // ONE TAP ZONE PER PASS, not one per group: three A's must still let you
      // jump to the second one. 22px of drawing, 44px of finger — and the
      // zones sit OUTSIDE the clipped drawing, or `overflow:hidden` would eat
      // the 11px of touch above and below the band.
      for(let i=0;i<g.n;i++){
        const t0=(g.t0!=null && g.t1!=null) ? g.t0+(g.t1-g.t0)*i/g.n : g.t0;
        const b=el("button",
          `position:absolute;top:0;bottom:0;left:${i*100/g.n}%;width:${100/g.n}%;`+
          `padding:${PAD}px 0;margin:-${PAD}px 0;border:0;background:transparent;z-index:2;`+
          `cursor:pointer;-webkit-tap-highlight-color:transparent;`);
        b.setAttribute("aria-label", name+(g.n>1?(" — pass "+(i+1)):""));
        b.onclick=()=>{
          haptic();
          const dur=totalDur()||1;
          if(t0!=null && S.audio){ seekFrac(t0/dur); }
          else { setPlayhead(g.rb0>=0?g.rb0:0, 0, t0); }
          // Scroll to a RENDERED bar: g.b0 is a SONG bar and overshoots the
          // folded grid (This Love: song bars run to 79, the grid has 25 rows).
          const cell=(S._cells||[]).find(c=>c.bar===g.rb0);
          if(cell) cell.el.scrollIntoView({block:"center",behavior:"smooth"});
        };
        seg.appendChild(b);
      }

      S._formChips.push({el:seg, vis, head, tag:tw, t0:g.t0, t1:g.t1});
      rail.appendChild(seg);
    });

    paintFormRail(S.playTime);   // unchanged contract — still keyed on TIME
    return wrap;
  }

  /* The band's playhead. The tint fills the CURRENT segment left to right in
     proportion to how much of it has played, so a long A reads as "we are two
     thirds through this A" and not merely "we are somewhere in an A" — which
     is the whole reason the 44px chips were worth losing. Written per segment
     from TIME alone, never from the segment's index: formRuns() orders by song
     bar, not by clock, so "every segment before the current one" is not a
     statement this code is allowed to make. A segment with no usable span (an
     iReal import) simply fills whole when it is the current one. */
export function paintFormRail(t){
    paintFormChip(t);                 // decides S._formChipCur, writes nothing
    const cur=S._formChipCur;
    (S._formChips||[]).forEach((c,i)=>{
      const on = i===cur;
      let f=0;
      if(t!=null && isFinite(t) && c.t0!=null && c.t1!=null && c.t1>c.t0)
        f=Math.min(1, Math.max(0, (t-c.t0)/(c.t1-c.t0)));
      else if(on) f=1;
      if(c.head) c.head.style.width=(f*100)+"%";
      if(c.vis)  c.vis.style.borderColor = on ? T.accent : T.line;
      if(c.tag)  c.tag.style.fontWeight = on ? "800" : "700";
    });
  }
  // Highlight the chip the playhead is inside, mirroring the bar highlight so
  // both surfaces agree about where you are. Keyed on TIME, not on bar index.
  // The two surfaces count bars in DIFFERENT spaces: the grid writes each
  // section once and replays it (A×4 = 8 rendered bars played on 4 passes), so
  // setPlayhead's index runs 0..24 here, while the chips span SONG bars 0..79.
  // Comparing them lit the first chip almost always — the "form timeline stuck
  // on A" bug (Louis, iPhone, 2026-07-30; measured 9 of 10 scrub positions on
  // This Love landing on chip 0 while the bar highlight was correct throughout).
  // Seconds are the one coordinate both surfaces share.
  //
  // PICK THE CHIP THAT CONTAINS t (2026-07-30, second report: "no highlighting
  // of the timeframe that explains the chord sequences (Ax3 B Ax2 ..) on top").
  // The rule used to be "the last chip whose t0 <= t", which silently assumes
  // the chips are in TIME order. They are not: formRuns() sorts occurrences by
  // SONG BAR, because that is the order the chart reads in — and a section whose
  // span is broken upstream (an iReal import with no times gives [0,0]) can sit
  // last in the strip while claiming t0 = 0. Then "last chip with t0 <= t"
  // matched that dead chip for EVERY t, pinning the highlight there so it never
  // tracked the music. Measured on 7 of 59 charts. Containment does not care
  // about order; chips with no real span are skipped outright, and a t that
  // falls in a gap between runs keeps the most recent one that really started.
export function paintFormChip(t){
    if(!S._formChips) return;
    let cur=-1;
    if(t!=null && isFinite(t)){
      const live=S._formChips.map((c,i)=>({c,i}))
        .filter(x=>x.c.t0!=null && x.c.t1!=null && x.c.t1>x.c.t0);
      const inside=live.find(x=>t>=x.c.t0 && t<x.c.t1);
      if(inside) cur=inside.i;
      else{
        const started=live.filter(x=>x.c.t0<=t).sort((a,b)=>a.c.t0-b.c.t0);
        if(started.length) cur=started[started.length-1].i;
      }
    }
    // DECIDES, does not draw (T1, 2026-08-19). It used to also write
    // background/borderColor on the chip, which fought paintFormRail for the
    // same two properties; paintFormRail owns every pixel of the band now and
    // this function's only output is the index below.
    S._formChipCur=cur;
  }
  // LE BOUTON « Re-infer · N » EST PARTI (Louis, 2026-08-20) : il propageait
  // un accord corrigé sur ses voisins. Un accord corrigé à la main est
  // désormais gardé tel quel, point — c'est aussi ce que le repli respecte
  // maintenant (folding._write_position refuse de réécrire une mesure
  // confirmée).
  // buildLadder() and legendFor() are gone (UI refresh 2026-08-08, §2): the
  // level ladder is a row in the Aa sheet, the analyse legend is the one-line
  // kitLegend inside analyseLens(), and the annotate confidence line lives in
  // buildRibbon(). LEVEL_CAPTION stays — the Aa sheet prints it.
export const LEVEL_CAPTION={
    1:"Level 1 — triads only: the skeleton of the harmony, nothing to trip on.",
    2:"Level 2 — the three everyday 7th chords; added tones and inversions drop away.",
    3:"Level 3 — the full picture, exactly as detected."
  };
export function chordColor(ch){
    if(S.mode==="read") return T.ink;
    // "Key" mode (2026-07-21 rework): a chord's colour used to be keyFill(root) —
    // a fixed hue per pitch class, no scale awareness at all (the bug the user
    // caught: two chords sharing a scale could still get different-looking text
    // once the playhead's own highlight sat behind one of them). The text now
    // stays plain ink in every analyse sub-mode except Function; which SCALE is
    // in effect is shown by the halo drawn under runs of bars in buildIReal(),
    // not by the chord glyph's own colour.
    if(S.mode==="analyse") return S.colorMode==="function"?fnColor(ch.root,S.key):T.ink;
    return ch.confirmed?T.ink:confColor(ch.c);
  }
  // Annotate writes every chord EXACTLY as the chart does (Louis, 2026-08-08:
  // « les mêmes accords que dans le chart ») — doubt is carried by confColor's
  // tint alone; the depth ladder no longer strips shaky chords to the family.
export function chordDepth(ch){ return "exact"; }
export function buildIReal(){
    const frame=el("div",`position:relative;background:${T.paper};border:1px solid ${T.line};border-radius:8px;overflow:hidden;`);
    const grid=el("div","display:grid;grid-template-columns:repeat(4,minmax(0,1fr));");
    // A phone is 390px: four bars of "D♭maj7" at desktop size do not fit, and
    // a grid item's default min-width:auto silently widens the column instead
    // of shrinking the type — which pushed bars 3 and 4 of every row off the
    // clipped edge. minmax(0,1fr) + min-width:0 lets the column hold the line;
    // the glyph scales instead.
    const W=root.clientWidth||390, narrow=W<470;
    // SZ2 (two-chords-per-bar) used to be shrunk hard relative to SZ1
    // (ratio .65-.73) — user feedback 2026-07-21 comparing against iRealB:
    // there's room in the cell for these to read bigger. Narrowed the gap to
    // a .85-.87 ratio instead of upsizing outright, since a bar cell is a
    // fixed quarter of the row width regardless of chord count.
    // Densité iReal (Louis 2026-08-02): accords plus GROS dans des rangées
    // moins hautes — le glyphe remplit sa cellule au lieu de flotter dans du
    // vide vertical. BARH est LA hauteur de rangée (cellules réelles ET
    // fillers de closeRow — une seule constante, sinon le treillis casse).
    // Immersif (delta2 §6): « mêmes cellules, plus hautes » — la grille
    // respire en hauteur (ratio du handoff 88/74), les glyphes ne changent
    // PAS (les grossir aussi re-created le chevauchement des barres denses
    // en notation normale — vu au premier passage de vérification).
    const imm = S.screen==="chart" && S.chartChrome===false;
    const SZ1=narrow?26:32, SZ2=narrow?22:28, SZ3=narrow?15:19;
    // Densité (§6, 2026-09-17): la grille respirait trop pour un téléphone —
    // 2,5 sections à l'écran là où iRealB en montre 4. On descend les TROIS
    // constantes d'espacement (hauteur de rangée immersive, gap de section,
    // gap de fin). Les tailles de glyphe (SZ1/SZ2/SZ3) ne bougent PAS: elles
    // ont déjà été arbitrées contre iRealB, et les grossir a re-créé le
    // chevauchement des barres denses.
    const BARH=imm?(narrow?58:66):(narrow?56:64);
    // §3: une rangée qui ne porte QUE des mesures de fin est courte — une
    // mesure ne doit pas coûter la hauteur de quatre. C'est une hauteur par
    // RANGÉE, jamais par cellule: les fillers de gauche (§2) et de droite
    // prennent la même, sinon le treillis casse.
    const BARH_ENDING=Math.round(BARH*0.78);
    const secGap = narrow?16:18;
    S._cells=[];
    let rowCells=[];
    const bars=S.bars.map(b=>({sec:b.sec, secId:b.secId, secFirst:b.secFirst, reps:b.reps, beats:b.beats,
                               ending:b.ending, endingFirst:b.endingFirst, endingOwn:b.endingOwn,
                               chords:b.idxs.map(i=>({ch:S.chords[i], idx:i}))}));
    // Key/scale halo (2026-07-21 rework of the old per-root keyFill text colour).
    // chordKey is aligned 1:1 with S.chords — PER CHORD, not per bar (2026-07-21
    // fix: an earlier version sampled only each bar's FIRST chord, so a bar
    // holding e.g. "Cmaj7 A7" or "Dm7 G7" silently painted BOTH chords with the
    // first one's scale — exactly the case the user caught: A7 (a real V7/D-minor
    // pivot) was hidden under bar5's "A minor" colour instead of showing its own
    // "D minor", same for G7 inside bar6). A leading held/silent chord-less bar
    // has nothing to sample; it falls back to the song's home key.
    let chordKey=null;
    if(S.mode==="analyse" && S.colorMode==="key" && S.chords.length){
      chordKey=keyTrackFor(S.chords, S.key, S.keyMode);
    }
    const globalLens = S.mode==="analyse" && S.colorMode==="global";
    // Running scale label, in RENDER order — crosses bar and row boundaries so a
    // run-start is detected at the exact chord where the collection changes, not
    // per bar. Null means "nothing rendered yet"; the very first real segment
    // always counts as a run-start (see `changed` below) and a leading held/
    // silent bar with nothing to inherit falls back to the song's home key (bar
    // 1 of "The Jackson 5 - ABC" had neither, and went halo-less before this).
    let lastKeyLabel=null;
    // Le chiffrage de la mesure précédente — la marque ne s'écrit qu'au
    // CHANGEMENT. Part du chiffrage principal du morceau, pour qu'une grille
    // qui n'en change jamais n'écrive rien.
    let lastBeats=(S.model&&S.model.bpb)||4;
    // iReal-style layout (user request 2026-07-19): every section change starts
    // a NEW ROW (grid-column-start:1), even if the previous row is left short;
    // col/row are therefore tracked explicitly (bi%4 no longer holds). In Read
    // mode the Intro section collapses to a single label-only row — an intro's
    // bar count is noise on a lead sheet; Annotate/Analyse keep its bars so
    // N.C. cells stay correctable.
    let col=0,row=0,lastCh=null,endingAnchorCol=null;
    // Une RANGÉE est un bloc: même hauteur, même décalage haut, quatre
    // cellules toujours. rowH/rowMT sont posés au moment où la rangée s'ouvre
    // et relus par toutes ses cellules — vraies cellules ET fillers. Avant
    // (2026-09-17) les fillers rappelaient BARH en dur et n'avaient aucun
    // margin-top: une section de 3 mesures fermait donc sa rangée avec des
    // cellules parties `secGap` px trop haut.
    // `rowBare` (Louis, 2026-09-17: « pas de gris sur le reste de cette ligne
    // par contre ») — une rangée qui ne porte QUE des mesures de fin n'est
    // pas une rangée de treillis. Ses mesures de fin se dessinent en petite
    // boîte fermée, collée à la rangée du dessus; tout le reste de la ligne
    // est du papier nu, sans bordure et sans bordure basse. C'est l'écart
    // assumé au §2 du handoff, qui demandait un quadrillage complet: le
    // quadrillage rendait le trou lisible, la boîte le rend juste.
    let rowH=BARH, rowMT=0, rowBare=false;
    // §3/§4/§5: une fin est un BLOC de mesures consécutives portant la même
    // étiquette (`b.ending`). Sa longueur décide trois choses — la largeur du
    // crochet (§4), la hauteur courte de sa rangée (§3), et si les deux fins
    // peuvent s'aligner ou doivent repartir en colonne 1 (§5). Elle se lit en
    // avant dans `bars`, jamais dans le DOM déjà posé.
    const endingRun=(start,fromCol)=>{
      const first=bars[start], tag=first&&first.ending;
      if(!tag) return 0;
      // (la longueur d'un bloc sert à trois choses : la largeur du crochet,
      //  la hauteur courte d'une rangée nue, et l'arbitrage du §5)
      const cap=(fromCol==null?4:4-fromCol);
      let n=0;
      for(let k=start;k<bars.length&&n<cap;k++){
        const nb=bars[k];
        if(nb.ending!==tag) break;
        if(k>start&&(nb.secFirst||nb.endingFirst)) break;
        n++;
      }
      return n;
    };
    // Vrai quand les cellules CHORDÉES de la rangée qui s'ouvre en `start`
    // sont exclusivement des mesures de fin — le seul cas où §3 raccourcit.
    const rowIsEnding=(start,fromCol)=>{
      // Seule une fin qui a SA rangée la rend nue. La fin classique partage
      // la rangée de son préfixe: le treillis y reste entier.
      if(!(bars[start] && bars[start].endingOwn)) return false;
      const n=endingRun(start,fromCol);
      if(!n) return false;
      if(fromCol+n>=4) return true;          // la rangée est pleine de fins
      const nxt=bars[start+n];
      if(!nxt) return true;                  // fin du chart
      if(nxt.secFirst) return true;          // la suivante ouvre sa rangée
      if(nxt.ending&&nxt.endingFirst) return true;  // la fin suivante aussi
      return false;                          // une mesure ordinaire suit ici
    };
    // §1 — TOUTE rangée entamée est fermée. `fillRow` bouche les colonnes
    // restantes avec de vraies cellules bordées (pas du papier nu);
    // `closeRow` y ajoute la bordure basse, pour les rangées qu'un gap
    // (secGap) détache de la rangée suivante — une rangée pleine
    // suivie d'une rangée collée n'en veut pas, la border-top de la suivante
    // dessine déjà le trait et deux traits collés font 2px.
    const filler=c=>{
      const f=el("div",`min-height:${rowH}px;${rowMT?`margin-top:${rowMT}px;`:""}`);
      if(rowBare){ f.dataset.bare="1"; return f; }   // papier nu, aucune encre
      f.style.cssText+=`${c>0?`border-left:1px solid ${T.rule};`:""}${row>0?`border-top:1px solid ${T.rule};`:""}`;
      return f;
    };
    const fillRow=()=>{ while(col!==0&&col<4){ const f=filler(col); grid.appendChild(f); rowCells.push(f); col++; } };
    const closeRow=()=>{ fillRow(); rowCells.forEach(c=>{ if(!c.dataset.bare) c.style.borderBottom=`1px solid ${T.rule}`; }); };
    bars.forEach((b,bi)=>{
      // Louis, 2026-08-08: the chord-less leading intro does not print AT ALL
      // in Read — the form rail above still carries it. Analyse/Annotate keep
      // its bars (N.C. cells stay inspectable and correctable).
      if(S.mode==="read" && S._hiddenIntroId && b.secId===S._hiddenIntroId) return;
      // L'INTRO ÉCRIT SES ACCORDS, COMME TOUT LE MONDE (Louis, 2026-09-18 :
      // « fais en sorte qu'on affiche toujours les accords de l'intro »).
      // Elle se repliait en UNE rangée « intro … » en Read : sur Lost Without
      // U, quatre mesures jouées disparaissaient derrière trois points. La
      // raison d'origine (2026-08-08, « le compte de mesures d'une intro est
      // du bruit sur une lead sheet ») visait l'intro SANS accord — et
      // celle-là est déjà traitée une ligne plus haut, par `_hiddenIntroId`,
      // qui ne se lève que quand aucune mesure ne porte autre chose qu'un
      // N.C. Une intro qui a des accords n'a jamais rien eu à cacher.
      // A 1st ending CONTINUES the row its shared prefix left off on — it's
      // still the same A, not a new line (user correction 2026-07-21: my
      // earlier "always start a fresh row" was wrong, "c'est la suite du
      // A"). Only forced to wrap when the row is genuinely full (col===4,
      // same rule as any other bar) or a section changes. A 2nd+ ending
      // still forces its OWN row — it can't share a column with the 1st
      // ending's bars, so it has nowhere else to go but the next line.
      // `endingOwn` remplace le test `b.ending!=="1"` : ce n'est plus le
      // NUMÉRO qui dit si une fin prend sa propre rangée, c'est le bloc
      // lui-même (voir endingBlocks). La fin classique — `1.` d'une vraie
      // 1re/2e fin, ou `B` quand elle couvre plusieurs passes — continue la
      // rangée de son préfixe : « c'est la suite du A » (Louis, 2026-07-21).
      const endingHead = b.ending && b.endingFirst;
      const endingForcesBreak = endingHead && b.endingOwn;
      // A 2nd+ ending aligns under the 1st ending's column (real iRealB
      // convention — user 2026-07-21: "le 2 devrait être aligné avec le 1"),
      // not back at column 1. endingAnchorCol remembers where "1." landed.
      // §2 (2026-09-17): on n'y saute PLUS par grid-column-start. Un saut
      // laissait des colonnes sans cellule, donc sans bordure — d'où le trou
      // de papier nu pleine hauteur sur un tiers de l'écran, avec la mesure
      // de fin perdue à droite. On émet pour de vrai les cellules vides
      // bordées des colonnes 1..anchor, mêmes styles et même hauteur que la
      // rangée: le trou devient une continuation lisible du treillis.
      let skipToCol=null;
      // §5: la 2e fin s'aligne sous la 1re (convention iRealB, déjà validée)
      // — sauf si la 1re ne tient pas jusqu'au bout de la rangée depuis sa
      // colonne d'ancrage. Dans ce cas les DEUX fins repartent en colonne 1,
      // chacune sur sa rangée. (`anchorCol=3, endingLen=1` passe tout juste;
      // un `tail:2` bascule.)
      const firstEndingHead = endingHead && !b.endingOwn;
      const endingSpread = firstEndingHead && (col + endingRun(bi,null) > 4);
      if(b.secFirst && col!==0){closeRow(); col=0;row++;}
      // §1 — c'était LE bug: `row++` sans `closeRow()`, donc la rangée
      // laissée en plan n'avait ni ses cellules manquantes ni sa bordure
      // basse (la rangée `E- F#- | A B-` de la capture).
      else if(endingForcesBreak && col!==0){closeRow(); col=0;row++;}
      else if(endingSpread && col!==0){closeRow(); col=0;row++;}
      else if(col===4){col=0;row++;}
      if(endingForcesBreak){
        const a=(endingAnchorCol!=null?endingAnchorCol:0);
        if(a>0 && col===0) skipToCol=a;
      }
      const atRowStart=col===0;
      const rowBroke = skipToCol!=null;
      if(col===0||rowBroke){
        rowCells=[];
        // La rangée s'ouvre: sa hauteur, son décalage haut et son encre sont
        // décidés ici, une fois, pour toutes ses cellules (§3).
        rowBare = rowIsEnding(bi, rowBroke?skipToCol:col);
        // Louis, 2026-09-17: « je veux que la cellule soit collée à celle
        // d'en dessous ». Une rangée de fin ne respire plus au-dessus d'elle
        // — la 2e fin touche la 1re, les deux forment un bloc vertical à leur
        // colonne, comme les deux boîtes d'une reprise sur une partition.
        // C'est ce qui a retiré son dernier emploi à l'ancien `endingGap`.
        rowMT = b.secFirst ? secGap : 0;
        rowH  = rowBare ? BARH_ENDING : BARH;
      }
      if(rowBroke){ while(col<skipToCol){ const f=filler(col); grid.appendChild(f); rowCells.push(f); col++; } }
      if(firstEndingHead) endingAnchorCol=col;
      // Only when an ending genuinely opens its OWN row does it get the
      // section-style left inset + the hanging bracket (digit + tick sitting
      // in a margin-top gap ABOVE the row, so it doesn't read as the
      // previous row's underline — 2026-07-21 fix). Sharing a row with its
      // own prefix needs neither: the accent top border alone, sized to
      // this one cell, already reads as "the alternate tail" without
      // pushing its row out of alignment with its siblings.
      const endingOwnRow = endingHead && (atRowStart || rowBroke);
      // Le retrait de gauche d'une fin sur SA rangée ne sert qu'à laisser
      // passer le tick du crochet — 2px de large, posé à left:2px. Il valait
      // 21/26px du temps où le chiffre `1.` vivait DANS la cellule; §4 l'a
      // remonté dans le gap, et ces 21px poussaient les deux accords de la
      // 2e fin par-dessus la barre de mesure de droite (vu au rendu 390px).
      const leftPad = endingOwnRow ? (narrow?8:11) : (narrow?3:8);
      // §2: plus de `grid-column-start` pour les fins — les cellules vides
      // sont posées pour de vrai, le flux de la grille suffit. Il ne reste
      // utile que pour `b.secFirst`, où il garantit la colonne 1.
      const gridStart = b.secFirst ? 1 : null;
      const bpbQ=S.model.bpb||4;
      // Bar-expanded add-a-chord (2026-09-16): a bar with fewer onsets than
      // beats — including zero, a held "%" bar — has room to add one. Such a
      // bar routes EVERY tap (glyph or empty space alike) to the zoomed
      // dotted view instead of straight to the editor; a FULLY written bar
      // (one onset per beat already) keeps today's direct tap-to-edit
      // untouched below — there is nowhere to add.
      const roomToAdd = b.chords.length<bpbQ;
      // §7 (delta2 / design 4a): en écriture compacte, dès 2 accords la barre
      // les EMPILE À GAUCHE avec un écart fixe (flex) au lieu de les répartir
      // sur les temps. C'est le changement de layout qui fait tenir 4 accords
      // — le glyphe serré tout seul ne suffit pas. Ce qu'on perd: l'abscisse
      // ne dit plus le temps; on le lit au nombre d'accords dans la barre,
      // comme iReal depuis toujours. L'exception gardée: un accord hors temps
      // régulier (beat non entier) garde la grille proportionnelle, sinon le
      // chart ment. Le mode normal garde la grille de temps — le serrage est
      // le contrat de l'écriture compacte, pas un changement global.
      const tight = PREF.notation==="compact" && b.chords.length>=2 &&
        b.chords.every(({ch})=>ch.beat==null || ch.beat===Math.round(ch.beat));
      const tightPad = endingOwnRow ? leftPad : (b.chords.length>=4?7:9);
      const layoutCss = tight
        ? `display:flex;align-items:center;gap:${tightGap(b.chords.length)}px;padding:0 ${narrow?3:8}px 0 ${tightPad}px;`
        : `display:grid;grid-template-columns:repeat(${bpbQ},minmax(0,1fr));align-items:center;column-gap:2px;padding:0 ${narrow?3:8}px 0 ${leftPad}px;`;
      // §4: plus de `border-top:2px accent` sur les mesures de fin. Rien à
      // gauche n'arrêtait ce trait, donc il se lisait comme le soulignement
      // de la rangée du dessus (sur la capture: une barre de séparation, pas
      // l'ouverture d'une reprise). Le treillis reste neutre (T.rule); le
      // crochet est un DESSIN par-dessus, posé plus bas.
      // Sur une rangée nue (`rowBare`) la mesure de fin n'hérite pas du
      // treillis: elle se ferme elle-même en boîte. Pas de bordure haute —
      // la bordure BASSE de la rangée du dessus est déjà là, et elle y est
      // collée; à gauche en colonne 1 c'est la barre noire du chart qui
      // ferme; à droite il n'y a plus de voisin bordé pour le faire, donc
      // la dernière mesure de la fin porte sa propre bordure droite.
      const bareEdge = rowBare
        ? `${col>0?`border-left:1px solid ${T.rule};`:""}border-bottom:1px solid ${T.rule};`+
          `${endingRun(bi,col)<=1?`border-right:1px solid ${T.rule};`:""}`
        : `${col>0?`border-left:1px solid ${T.rule};`:""}${row>0?`border-top:1px solid ${T.rule};`:""}`;
      // Le crochet occupe les ~14px du haut de la cellule: sans ce retrait,
      // le chiffre `1.` se posait SUR l'accord (vu au rendu, colonne 1 d'une
      // fin partie en colonne 1). Il vaut pour TOUTES les mesures de la fin,
      // pas seulement sa tête, sinon la rangée perd sa ligne de base.
      const endingPadTop = b.ending ? `padding-top:${narrow?9:11}px;` : "";
      // LE CHANGEMENT DE CHIFFRAGE PREND SA PLACE (2026-09-18). iReal pose le
      // `2/4` DANS la mesure, à gauche, et pousse l'accord — pas par-dessus.
      // Sans ce retrait les deux chiffres se posaient sur le glyphe.
      const marqueChiffrage = !!b.beats && b.beats!==lastBeats;
      const meterPadLeft = marqueChiffrage ? `padding-left:${narrow?11:13}px;` : "";
      const cell=el("div",`position:relative;min-width:0;min-height:${rowH}px;${layoutCss}${endingPadTop}${meterPadLeft}${rowMT?`margin-top:${rowMT}px;`:""}${gridStart!=null?`grid-column-start:${gridStart};`:""}${bareEdge}`);
      // Scale halo: a coloured underline strip per CHORD, not per bar (2026-07-21
      // fix — see chordKey's own comment above for the "A7 hidden inside bar5"
      // bug this replaces). Never on `background` — setPlayhead() stomps that
      // property on the current bar, the same failure mode that caused the
      // original "two different colours for one scale" report. Segments are
      // evenly split across however many chords share this bar, so e.g. "Cmaj7
      // A7" gets two independently-coloured halves, not one shared colour.
      // Key lenses (new-chord-ux handoff #5): FULL-CELL colour bands, not the
      // old 4px underline — "full-cell vertical fill is the approved look;
      // per-chord pill and horizontal-strip variants were rejected". Cells
      // are edge-to-edge, so adjacent same-key cells read as one continuous
      // band. Bands are z-index:0 UNDER the glyphs (items are z-index:1);
      // the playhead's right-edge bar is appended after and stays visible.
      if(chordKey){
        const segs = b.chords.length
          ? b.chords.map(({ch,idx})=>ch.nc?null:chordKey[idx])
          : [lastKeyLabel || {tonic:S.key, mode:S.keyMode}];
        const n=segs.length;
        segs.forEach((k,i)=>{
          if(!k) return;
          const coll=collOf(k.tonic,k.mode), hue=keyHue(coll), minor=k.mode==="minor";
          const changed = !lastKeyLabel || collOf(lastKeyLabel.tonic,lastKeyLabel.mode)!==coll;
          const hb=b.chords.length?Math.max(0,Math.min(bpbQ-1,(b.chords[i].ch.beat!=null?b.chords[i].ch.beat:0))):0;
          const hw=b.chords.length?((i+1<n?Math.max(hb+1,Math.min(bpbQ,(b.chords[i+1].ch.beat!=null?b.chords[i+1].ch.beat:bpbQ))):bpbQ)-hb):bpbQ;
          cell.appendChild(el("div",`position:absolute;left:${hb/bpbQ*100}%;width:${hw/bpbQ*100}%;top:0;bottom:0;background:${lensBand(hue,minor)};z-index:0;pointer-events:none;`));
          if(changed){
            cell.appendChild(el("div",`position:absolute;left:calc(${i/n*100}% + 2px);bottom:3px;font:700 ${narrow?8:9.5}px ${UI};letter-spacing:.01em;color:${lensLabelColor(hue,minor)};z-index:2;pointer-events:none;white-space:nowrap;`,keyLabelName(k.tonic,k.mode)));
          }
          lastKeyLabel=k;
        });
      }
      if(globalLens){
        const coll=collOf(S.key,S.keyMode), hue=keyHue(coll), minor=S.keyMode==="minor";
        cell.appendChild(el("div",`position:absolute;inset:0;background:${lensBand(hue,minor)};z-index:0;pointer-events:none;`));
      }
      // LE CHANGEMENT DE CHIFFRAGE, ÉCRIT (2026-09-18). iReal pose un `2/4`
      // devant la mesure qui n'a que deux temps, et un `4/4` sur celle qui
      // reprend — on fait pareil, et seulement quand ça CHANGE: une grille
      // en 4/4 du début à la fin ne porte aucune marque. Posé en haut à
      // gauche de la cellule, au-dessus des bandes de tonalité, jamais dans
      // le flux des accords (il ne doit pas décaler un glyphe).
      if(marqueChiffrage){
        // Centré en hauteur dans la cellule, comme un chiffrage de portée —
        // et sous le crochet de reprise quand la mesure ouvre une fin.
        const d=el("div",`position:absolute;left:1px;top:calc(50% + ${b.ending?(narrow?5:6):0}px);transform:translateY(-50%);z-index:2;pointer-events:none;display:flex;flex-direction:column;align-items:center;line-height:.9;font:700 ${narrow?8.5:10}px ${UI};color:${T.faint};`);
        d.appendChild(el("span","",String(b.beats)));
        d.appendChild(el("span","","4"));
        cell.appendChild(d);
      }
      if(b.beats) lastBeats=b.beats;
      if(b.secFirst){
        // Louis 2026-08-02: le badge vit AU-DESSUS de la rangée (dans le
        // gap secGap), plus DANS la barre — les accords ne sont plus
        // décalés. Les ×N n'apparaissent que dans la strip FORM en tête.
        // §6: secGap est descendu à 16/18 — le badge doit tenir DANS le gap
        // sans mordre la bordure de sa rangée, donc il se pose au ras de
        // celle-ci (top:-(secGap-1)) au lieu de flotter à -(secGap-3).
        cell.appendChild(el("div",`position:absolute;left:0;top:-${secGap-1}px;font:800 ${narrow?9:11}px ${UI};line-height:1;color:${T.accent};border:1.5px solid ${T.accent};border-radius:4px;padding:1px 4px;background:${T.paper};z-index:2;`,b.sec));
        // (la barre noire d'ouverture de section a disparu d'ici: Louis en
        // veut UNE, continue sur toute la hauteur du chart — elle est posée
        // une seule fois sur le cadre, tout en bas de cette fonction.)
      }
      if(endingHead){
        // §4 — UN VRAI CROCHET DE REPRISE, dessiné par-dessus le treillis.
        //   * tick vertical, 2px accent, ~14px, à `left:2px` de la cellule de
        //     tête — c'est lui qui arrête le trait à gauche;
        //   * horizontale 2px accent partant du tick et s'arrêtant AU BORD
        //     DROIT de la dernière mesure de cette fin, jamais au-delà (d'où
        //     `endingRun`: les cellules font 1fr chacune, donc n mesures =
        //     n×100% de la largeur de la cellule de tête);
        //   * le chiffre `1.`/`2.` au-dessus de l'horizontale, dans le gap.
        // Quand la fin PARTAGE sa rangée il n'y a pas de gap où poser le
        // chiffre: crochet et chiffre rentrent alors juste sous le bord haut
        // de la cellule, le chiffre décalé à droite du tick.
        // Une rangée de fin est désormais COLLÉE à celle du dessus (Louis,
        // 2026-09-17): il n'y a plus de gap où faire pendre le chiffre, donc
        // le crochet entier rentre sous le bord haut de la cellule, chiffre
        // à droite du tick — l'écriture classique d'une volta.
        const span=Math.max(1,endingRun(bi,col));
        const y = 1;
        cell.appendChild(el("div",`position:absolute;left:2px;top:${y}px;height:2px;width:calc(${span*100}% - 6px);background:${T.accent};z-index:3;pointer-events:none;`));
        cell.appendChild(el("div",`position:absolute;left:2px;top:${y}px;width:2px;height:${narrow?13:15}px;background:${T.accent};z-index:3;pointer-events:none;`));
        cell.appendChild(el("div",
          `position:absolute;left:7px;top:${y+3}px;`+
          `font:800 ${narrow?9:11}px ${UI};line-height:1;color:${T.accent};z-index:3;pointer-events:none;`,
          b.ending));
      }
      // Learn reduction can collapse two different chords in one bar to the
      // same label (B♭maj7 · B♭7 both read B♭ at L1). A lead sheet never
      // prints the same chord twice inside one bar, so the duplicate is
      // dropped — only in Learn; L3/Advanced always shows the full picture.
      let prevInBar=null;
      b.chords.forEach(({ch,idx})=>{
        if(S.learn && !ch.nc){
          const key=ch.root+"|"+dispQ(ch.q);
          if(prevInBar===key) return;
          prevInBar=key;
        } else prevInBar=null;
        const q4=Math.max(0,Math.min(bpbQ-1,(ch.beat!=null?ch.beat:0)));
        // Annotate renders chords as <button>; a 44×44 minimum grows the TAP
        // target to the kit floor without moving the glyph (the cell is
        // 56-64 tall so the box fits; in a dense 3-4 chord bar the 44-wide
        // boxes overlap and DOM order arbitrates — each glyph itself always
        // stays inside its own exclusive zone).
        // 3-4 chords/bar (trusted iReal walking turnarounds) need a third,
        // smaller size tier — SZ1/SZ2 alone only split 1 vs >1 (2026-07-21).
        // En serré (§7) la taille suit le nombre d'accords: 30/25/22/19,
        // plancher dur à 19 — la seule échelle, quel que soit narrow.
        const size=tight?tightSize(b.chords.length):(b.chords.length>=3?SZ3:(b.chords.length>1?SZ2:SZ1));
        // Learn mode relabels through the ladder (dispQ); slash bass is an
        // L3 concept and hides below it. The tiny amber tag marks cells whose
        // label genuinely simplified, so Learn never silently lies.
        // (Défini ICI, avant la boîte: la mise en page de la pédale en dépend.)
        const bassHidden=S.learn&&S.level<3&&ch.bass!=null&&ch.bass>=0&&mod(ch.bass,12)!==mod(ch.root,12);
        // `ch.pedal` = l'accord ne change pas, seule la basse bouge (iReal
        // `W/G♭`). On n'écrit que la basse, comme iReal — sauf en Learn sous
        // L3, où la basse slash n'existe pas encore : là, l'accord complet
        // revient, sinon la case serait vide.
        const pedale=ch.pedal && ch.bass!=null && ch.bass>=0 && !bassHidden;
        // LA BASSE PÉDALE EST SUSPENDUE, PAS ALIGNÉE (2026-09-18). iReal écrit
        // le refrain de Virtual Insanity `E♭m7 · ⌄G♭ · A♭m11 · ⌄B♭` : la 2e et
        // la 4e case ne prennent AUCUNE largeur, elles pendent sous l'accord
        // précédent. C'est ce qui fait tenir quatre cases dans une mesure — en
        // flux, la même mesure débordait de sa cellule. Sortie du flux, donc,
        // à l'abscisse de son propre temps et juste sous la ligne d'accords.
        // Pas en Annotate : là, la cible de 44px prime sur la densité.
        const pendu = pedale && S.mode!=="annotate";
        const place = pendu
          ? `position:absolute;left:calc(${q4/bpbQ*100}% + 1px);top:calc(50% + ${Math.round(size*0.16)}px);z-index:2;`
          : `position:relative;z-index:1;${tight?"":`grid-column:${q4+1};grid-row:1;justify-self:start;`}`;
        const item=el(S.mode==="annotate"?"button":"div",`${place}min-width:0;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:2px;background:none;border:none;cursor:${ch.nc&&S.mode!=="annotate"?"default":"pointer"};padding:0 ${tight||pendu?0:2}px;${S.mode==="annotate"?"min-height:44px;min-width:44px;":""}${ch.carry?"opacity:.72;":""}`);

        // No-chord (N.C.) cell: music-x-lab detected silence/no harmony here.
        // Render a faint "N.C." rather than an invented glyph (the intro/outro
        // of a track, or an a-cappella bridge) — known_issues.md 2026-07-19
        // * CHORDS / NO-CHORD. Still clickable in annotate mode to override.
        if(ch.nc){
          item.appendChild(el("div",`font:italic 600 ${narrow?15:18}px ${SERIF};color:${T.faint};opacity:.55;`,"N.C."));
          // A bar with room to add (roomToAdd) routes ANY tap — glyph or empty
        // space alike — to the bar-expanded dotted view instead (see the
        // cell-level handler below): the direct tap-to-edit stays only for a
        // fully written bar, where there is no empty beat to route to.
        if(S.mode==="annotate" && !roomToAdd) item.onclick=()=>openEditor(idx);
          cell.appendChild(item);
          return;
        }
        const dq=dispQ(ch.q);
        item.appendChild(pedale
          ? pedalGlyph(ch.bass,size,chordColor(ch))
          : glyph(ch.root,dq,size,chordDepth(ch),chordColor(ch),bassHidden?-1:ch.bass,b.chords.length===1));
        // LA VARIANTE, en petit au-dessus — comme iRealb (Louis, 2026-08-17 :
        // « indiquer le moins commun comme une variation, en petit en haut de
        // l'accord comme on fait sur irealb »). Elle n'apparaît que sur un
        // chart replié qui la porte : c'est l'autre lecture que le morceau
        // donne à cette case, quand les tours repliés ne s'accordent pas et
        // qu'aucun pattern n'explique l'écart. Elle ne remplace jamais
        // l'accord, elle le commente. Posée côté serveur depuis le
        // 2026-09-16 (`harmonia.folding._bar_variant`, Easy On Me : « j'aimerais
        // avoir juste F affiché et le D-7 en optionnel en petit au-dessus en
        // suggestion, comme iReal fait ») — un objet {root,q,bass,c,n}, pas
        // une chaîne déjà mise en forme : on la dessine avec le MÊME `glyph()`
        // que l'accord principal, en plus petit, pour hériter gratuitement de
        // son orthographe correcte selon le ton (`noteEl`/`setSpelling`,
        // 2026-09-16) au lieu de la réinventer ici.
        if(ch.var) {
          const vw=el("span","position:absolute;top:-7px;right:-4px;opacity:.85;pointer-events:none;line-height:1;");
          vw.appendChild(glyph(ch.var.root,dispQ(ch.var.q),narrow?9:10,"exact",T.accent,
            (ch.var.bass==null?-1:ch.var.bass)));
          item.appendChild(vw);
        }
        if(S.learn&&(dq!==ch.q||bassHidden)) item.appendChild(el("span",`font:600 8px ${UI};color:${T.amber};`,"simpler"));
        // LA RANGÉE DE MARQUE (T4, 2026-08-19). Une seule rangée sous le
        // glyphe, 5 px, TOUJOURS présente en Annotate même vide : réservée, elle
        // ne fait sauter aucune ligne de base quand une case gagne ou perd sa
        // marque. Elle porte l'une ou l'autre, jamais les deux.
        //   * pas sûr  → un point de 5 px, couleur de confiance. Il remplace le
        //     « ? » posé en top:-4px;right:-2px, qui sortait de la case et
        //     chevauchait la barre de mesure et la ligne du dessus.
        //   * verrouillé → un tiret vert de 14×2. Il remplace le mot « locked »,
        //     qui coûtait une ligne de texte entière pour dire ce qu'une marque
        //     dit d'un coup d'œil.
        // Pas de percentage (2026-07-30) : le score du modèle lisait 36 pp trop
        // bas, AUC 0.480 — il ne classait pas les bons accords au-dessus des
        // mauvais. La COULEUR est la confiance, et elle vient du nombre de fois
        // que le morceau rejoue cet accord (chord_confidence.py) ; le point
        // marque l'accord que le morceau ne rejoue jamais — juste 14 % du temps,
        // le seul signal sur lequel il vaut la peine d'agir.
        // En Read et en Analyse : rien. La couleur du texte suffit.
        if(S.mode==="annotate"){
          const mk=el("div","flex:0 0 auto;display:flex;align-items:center;height:5px;margin-top:1px;");
          if(ch.confirmed)
            mk.appendChild(el("div",`width:14px;height:2px;border-radius:1px;background:${T.green};`));
          else if(ch.c<.42)
            mk.appendChild(el("div",`width:5px;height:5px;border-radius:50%;background:${confColor(ch.c)};`));
          item.appendChild(mk);
        }
        const gt=gtForSpan(ch.t0,ch.t1);
        if(gt){
          const ok=gtMatches(gt,ch);
          item.appendChild(el("span",
            `font:italic 600 ${narrow?9:10.5}px ${SERIF};color:${ok?T.faint:T.accent};opacity:${ok?.75:1};margin-top:1px;white-space:nowrap;`,
            "GT "+gt.text+(gt.extra?"…":"")));
        }
        // A bar with room to add (roomToAdd) routes ANY tap — glyph or empty
        // space alike — to the bar-expanded dotted view instead (see the
        // cell-level handler below): the direct tap-to-edit stays only for a
        // fully written bar, where there is no empty beat to route to.
        if(S.mode==="annotate" && !roomToAdd) item.onclick=()=>openEditor(idx);
        // Read/Analyse à l'arrêt: tap → la grande feuille (piano + voicings —
        // c'est là qu'on édite). En LECTURE Read (§6 delta2): "tap" fait
        // monter la carte de voicing par-dessus la grille sans couper
        // l'audio; "follow" garde la feuille (le clavier du bas suit déjà);
        // "never" ne monte rien — la grille reste seule.
        else if(S.mode!=="annotate"){
          item.setAttribute("data-chord-cell","1");
          item.onclick=()=>{
            if(tapSeeks()){ seekToBar(bi); return; }
            if(S.playing && S.mode==="read"){
              if(S.piano==="tap") openVoicingCard(idx, cell);
              else if(S.piano==="follow") openChordSheet(idx);
            } else openChordSheet(idx);
          };
        }
        cell.appendChild(item);
        lastCh=ch;
      });
      // Held bar: no chord of its own — the previous chord sounds through it.
      // A faint "%" (simile) reads fine when the bar it repeats is right
      // there on the same row — but never at the START of a row (user rule
      // 2026-07-20): the previous bar is above, out of view, so "%" means
      // nothing on its own. Re-spell the actual chord there instead.
      if(!b.chords.length){
        if(atRowStart && lastCh){
          const item=el("div","position:relative;z-index:1;min-width:0;display:flex;flex-direction:column;align-items:center;gap:2px;grid-column:1/-1;justify-self:center;");
          item.appendChild(glyph(lastCh.root,dispQ(lastCh.q),SZ1,chordDepth(lastCh),chordColor(lastCh),(S.learn&&S.level<3)?-1:lastCh.bass,true));
          cell.appendChild(item);
        } else {
          cell.appendChild(el("div",`position:relative;z-index:1;font:700 ${narrow?22:28}px ${SERIF};color:${T.faint};opacity:.5;grid-column:1/-1;justify-self:center;`,"%"));
        }
      }
      const ph=el("div",`position:absolute;right:0;top:0;bottom:0;width:3px;background:${T.accent};display:none;`); cell.appendChild(ph);
      const sel=el("div","position:absolute;inset:0;pointer-events:none;display:none;");
      cell.appendChild(sel);
      cell.dataset.bar=String(bi);
      // Sur la CELLULE, pas seulement sur le glyphe : une mesure tenue (« % »)
      // ou vide n'a aucun accord à taper, et c'est justement une mesure où on
      // veut pouvoir reprendre. Le tap sur un accord passe par le même appel,
      // donc les deux ne peuvent pas se contredire.
      // Le réglage est lu AU CLIC, pas à la construction : le basculer dans la
      // feuille Aa agit tout de suite, sans re-rendre la grille sous une
      // feuille ouverte.
      if(S.mode!=="annotate" && !sectToolOn()) cell.onclick=()=>{ if(tapSeeks()) seekToBar(bi); };
      else if(S.mode==="annotate" && !sectToolOn() && roomToAdd) cell.onclick=()=>openBarExpanded(bi);
      S._cells.push({el:cell, bar:bi, idxs:b.chords.map(x=>x.idx), ph, sel});
      grid.appendChild(cell);
      rowCells.push(cell);
      col++;
    });
    // fermer la toute dernière rangée du chart — exactement les mêmes règles
    // que partout ailleurs, via le même `closeRow` (rowH/rowMT compris, §3).
    closeRow();
    frame.appendChild(grid);
    // LA BARRE NOIRE, TOUT DU LONG (Louis, 2026-09-17). C'était un trait par
    // SECTION, posé dans la cellule `secFirst` et haut d'une seule rangée:
    // le chart en portait un par section, interrompu partout ailleurs. Une
    // seule barre sur le cadre, du haut au bas de la grille — la marge
    // gauche du morceau, pas une marque de section. Posée APRÈS la grille
    // pour passer devant les bandes de tonalité, comme les badges.
    frame.appendChild(el("div",
      `position:absolute;left:0;top:0;bottom:0;width:2px;background:${T.ink};z-index:2;pointer-events:none;`));
    if(sectToolOn()) attachSectionDrag(grid);
    paintSectionTool();
    setPlayhead(S.playBar, S.playRep, S.playTime);
    return frame;
  }

